"use client";
import {useEffect,useMemo,useState} from "react";

type Module={id:string;label:string;title:string;sub:string;time:string;color:string;status:string;lessons:Lesson[]};
type Lesson={title:string;stage:string;time:string;objective:string;topics:string[];judgement:string;example:string;check:{q:string;o:string[];a:number;why:string}};
const shared=(q:string,o:string[],a:number,why:string)=>({q,o,a,why});
const modules:Module[]=[
 {id:"dff",label:"DFF",title:"Descriptive Flexfields",sub:"Add business-specific attributes to an existing object or transaction.",time:"75 min",color:"coral",status:"AVAILABLE",lessons:[
  {stage:"ORIENT",title:"What a DFF is — and is not",time:"10 min",objective:"Recognise when the standard application needs additional descriptive data.",topics:["Base table extension columns","Global vs context-sensitive segments","Where DFFs appear in the UI","Why a DFF is not a new business object"],judgement:"Use a DFF when the data describes an existing record and belongs with its lifecycle.",example:"Capture Professional Membership Number on the Person record.",check:shared("The business needs a field called Uniform Size for workers. No separate record history is required. Best fit?",["Person DFF","Person EFF","Accounting KFF"],0,"It is one additional descriptive attribute on an existing person record.")},
  {stage:"DESIGN",title:"Find the correct flexfield",time:"12 min",objective:"Identify the business object, flexfield code and usage before configuration.",topics:["Setup and Maintenance navigation","Manage Descriptive Flexfields","Flexfield code and table mapping","Usage and page availability"],judgement:"Never configure against a similarly named flexfield until you confirm the owning object and UI usage.",example:"Worker assignment data belongs on the assignment DFF, not the person DFF.",check:shared("A field changes when an employee transfers assignments. Where should it live?",["Person-level DFF","Assignment-level DFF","Location KFF"],1,"Assignment-specific data must follow the assignment lifecycle.")},
  {stage:"MODEL",title:"Contexts, segments and value sets",time:"18 min",objective:"Build global and conditional fields with controlled values.",topics:["Global segments","Context segment and context codes","Context-sensitive segments","Character, number and date value sets","Independent and table-validated lists"],judgement:"Create a context only when a meaningful condition changes which fields the user should see.",example:"Show Vehicle Registration only when Travel Type is Company Car.",check:shared("A segment should appear only for UK employees. Which design is most suitable?",["Global segment","UK context-sensitive segment","A new KFF structure"],1,"A context condition controls when the segment appears.")},
  {stage:"CONFIGURE",title:"Configure, deploy and expose",time:"15 min",objective:"Follow the safe setup sequence and understand deployment impact.",topics:["Create and order segments","Prompts, display type and required flags","BI Enabled setting","Save, validate and deploy","Page Composer / VB Studio visibility considerations"],judgement:"Deployment is a controlled technical change; coordinate it and retest every surface that consumes the flexfield.",example:"Deploy Assignment DFF, expose it in Redwood, then verify responsive and data-loader behaviour.",check:shared("A configured segment is not available for OTBI. What should you inspect first?",["BI Enabled and deployment","Worker security role only","KFF delimiter"],0,"The segment must be BI-enabled and the flexfield successfully deployed.")},
  {stage:"PROVE",title:"Load, report and test",time:"20 min",objective:"Validate the full lifecycle—not merely field visibility.",topics:["Create and edit tests","Required-field and value-set negatives","HDL attribute mapping","OTBI/BI Publisher exposure","Regression after quarterly updates"],judgement:"A DFF is complete only when UI, security, integration, history and reporting behave as designed.",example:"Test a valid membership number, invalid format, HDL load, correction and OTBI output.",check:shared("Which is the strongest test pack?",["Field displays and saves","UI save + negative validation + HDL + reporting + security","Successful deployment only"],1,"End-to-end coverage proves every consuming channel.")}
 ]},
 {id:"eff",label:"EFF",title:"Extensible Flexfields",sub:"Model repeatable, category-aware information with richer structures.",time:"90 min",color:"violet",status:"AVAILABLE",lessons:[
  {stage:"ORIENT",title:"When an EFF is the right model",time:"12 min",objective:"Distinguish richer extensible data from a simple descriptive field.",topics:["Extension tables","Multiple rows and contexts","Categories and context association","Effective dating where supported"],judgement:"Choose an EFF when the requirement needs structured, repeatable or categorised information—not because it has many fields.",example:"Maintain multiple licences for a person, each with type, authority, issue and expiry date.",check:shared("A worker can hold several professional licences. Best model?",["One Person DFF text field","Person EFF with repeatable rows","Accounting KFF"],1,"Multiple structured licence records suit a repeatable EFF context.")},
  {stage:"ARCHITECT",title:"Categories, contexts and pages",time:"18 min",objective:"Understand the EFF hierarchy before creating segments.",topics:["EFF category","Context usage","Single-row vs multiple-row contexts","Context behaviour","Page association and display"],judgement:"Sketch category → context → segment relationships before touching configuration.",example:"Talent Profile category contains Language and Professional Accreditation contexts.",check:shared("What determines how contexts are grouped for a business purpose?",["Value set","Category","KFF structure instance"],1,"Categories organise the contexts associated with an EFF usage.")},
  {stage:"MODEL",title:"Design repeatable data safely",time:"20 min",objective:"Set cardinality, validation and ownership rules.",topics:["Row uniqueness","Required segments","Date and lookup validation","Context security","Data ownership and retention"],judgement:"If multiple rows are allowed, define what makes a row unique and how obsolete rows are ended or removed.",example:"Licence Type + Issuing Country + Number forms the functional uniqueness rule.",check:shared("Before allowing multiple rows, what is essential?",["A colour for each row","A business uniqueness and lifecycle rule","A new legal employer"],1,"Without uniqueness and lifecycle rules, duplicate and stale records accumulate.")},
  {stage:"CONFIGURE",title:"Configure and deploy the EFF",time:"18 min",objective:"Create contexts, segments and category associations in the correct order.",topics:["Manage Extensible Flexfields","Create context and segments","Associate context to category","Configure usage","Validate and deploy"],judgement:"An EFF context can be technically valid yet unavailable because category or usage association is missing.",example:"Create Certification Details, attach to Person EFF category, deploy, then expose on the intended page.",check:shared("A deployed context does not appear. What is a likely cause?",["Missing category/usage association","No KFF delimiter","Approval routing is disabled"],0,"Deployment alone does not establish the required category and usage relationship.")},
  {stage:"INTEGRATE",title:"Security, HDL and reporting",time:"22 min",objective:"Prove downstream behaviour for single and multiple-row data.",topics:["EFF business object components in HDL","Source keys and row maintenance","Role and context security","BI subject-area availability","Extract and integration design"],judgement:"Treat each EFF row like governed business data with stable keys, not an unstructured note.",example:"Load two licences, update only one using its source key, restrict sensitive context, and report current licences.",check:shared("Why are stable source keys especially important for multi-row EFF data?",["They select the correct row for update","They change the display colour","They deploy the flexfield"],0,"The key identifies which repeatable record should be maintained.")}
 ]},
 {id:"kff",label:"KFF",title:"Key Flexfields",sub:"Create meaningful, validated codes that identify and classify business entities.",time:"95 min",color:"blue",status:"AVAILABLE",lessons:[
  {stage:"ORIENT",title:"The purpose of a KFF",time:"12 min",objective:"Understand why key flexfields build intelligent business identifiers.",topics:["Concatenated combinations","Segments as meaningful parts","Code combinations","Operational examples: Accounting, Job, Position"],judgement:"A KFF identifies or classifies an entity through a governed combination; it is not a place for miscellaneous attributes.",example:"A position code combines Business Unit–Function–Location–Level.",check:shared("Which requirement best fits a KFF?",["Add a dietary preference field","Build a validated multi-segment position code","Store multiple licences"],1,"The requirement creates a structured identifying combination.")},
  {stage:"STRUCTURE",title:"Structures and structure instances",time:"20 min",objective:"Separate the reusable segment blueprint from its business-specific implementation.",topics:["Flexfield structure","Structure instance","Segment sequence","Delimiter and concatenation","Dynamic insertion"],judgement:"Use multiple structures only when the identifier genuinely has different segment architecture—not merely different values.",example:"Different legislative groups may share a Job KFF structure but use separate structure instances and value sets.",check:shared("What applies a KFF structure to a specific business use?",["Context code","Structure instance","DFF usage"],1,"The instance operationalises the structure for a defined use.")},
  {stage:"VALIDATE",title:"Value sets and combination rules",time:"22 min",objective:"Control valid values and prevent invalid cross-segment combinations.",topics:["Independent and table value sets","Parent-child validation","Cross-validation rules","Segment labels and qualifiers","Dynamic combination risks"],judgement:"A segment can contain a valid value while the overall combination is still invalid.",example:"Location UK-LON cannot be combined with Legal Entity US01.",check:shared("Both individual segment values are valid, but their pairing is prohibited. What controls this?",["Cross-validation rule","EFF category","DFF context"],0,"Cross-validation evaluates the combination across segments.")},
  {stage:"CONFIGURE",title:"Configure, freeze and deploy",time:"18 min",objective:"Follow the more consequential KFF deployment lifecycle.",topics:["Define structure and segments","Assign value sets and labels","Create instance","Freeze definition","Deploy and test combinations"],judgement:"KFF structure changes can affect existing combinations, integrations and reports; design for long-term stability.",example:"Freeze and deploy a Position KFF only after integration owners approve segment order and delimiter.",check:shared("Why should segment order be agreed early?",["It affects stored combinations and consumers","It only changes page colour","It controls approval FYIs"],0,"The concatenated identifier is consumed broadly and is costly to restructure.")},
  {stage:"OPERATE",title:"Govern combinations over time",time:"23 min",objective:"Control creation, end-dating, security and downstream use.",topics:["Combination creation governance","Dynamic insertion on/off","End-date values vs combinations","Mass loads and reconciliation","Integration and reporting contracts"],judgement:"Do not let convenience-driven dynamic insertion undermine master-data ownership.",example:"Restrict new Position code combinations to HR Operations and reconcile loads against approved structures.",check:shared("What is the key risk of unrestricted dynamic insertion?",["Users create ungoverned combinations","EFF rows disappear","DFF contexts deploy twice"],0,"New combinations may bypass master-data controls.")}
 ]},
 {id:"approvals",label:"APP",title:"Approval Design",sub:"Translate policy into defensible routing, controls and tests.",time:"55 min",color:"green",status:"AVAILABLE",lessons:[
  {stage:"FOUNDATIONS",title:"Anatomy of an approval",time:"8 min",objective:"Connect transaction data, rules, participants and routing.",topics:["Transaction attributes","Rule conditions","Participants","Routing outcomes"],judgement:"Every approver must trace to a policy need and resolvable transaction data.",example:"An India-to-UK transfer resolves current and receiving actors.",check:shared("What should drive every approver in the route?",["A policy need","Page layout","Personal preference"],0,"Approval design must remain defensible against the policy.")},
  {stage:"TRANSLATE",title:"Policy → rule logic",time:"12 min",objective:"Turn business language into precise conditions and actions.",topics:["Entry criteria","Boolean logic","Threshold boundaries","Rule priority"],judgement:"Write the expected outcome before configuring the rule.",example:"Salary increase >15% adds Compensation Manager.",check:shared("Grade 7+ should be expressed as?",["=7",">7","≥7"],2,"The threshold includes Grade 7.")},
  {stage:"PEOPLE",title:"Build the approver chain",time:"10 min",objective:"Choose the correct participant types and order.",topics:["Supervisory hierarchy","Representatives","Job/position levels","Serial vs parallel"],judgement:"Choose a participant type that reliably resolves at runtime.",example:"Current HRBP and receiving HRBP may resolve from different AORs.",check:shared("Two approvals must happen in order. Use?",["Serial routing","Parallel routing","FYI only"],0,"Serial routing enforces sequence.")},
  {stage:"CONTROLS",title:"Design without dead ends",time:"15 min",objective:"Handle duplicates, self-approval and missing participants.",topics:["Skip creator","Duplicate resolution","Empty group handling","Escalation and expiry"],judgement:"Design explicitly for who initiates and what happens when an approver is absent.",example:"Receiving HRBP initiates the transfer and must not approve their own transaction.",check:shared("Current and receiving HRBP are the same. Best outcome?",["Approve twice","Approve once","Skip both"],1,"De-duplication keeps one valid approval.")},
  {stage:"VALIDATE",title:"Test what you designed",time:"10 min",objective:"Build positive, negative and boundary test scenarios.",topics:["Boundary values","Role resolution","Rule combinations","Audit evidence"],judgement:"One happy-path transaction never proves an approval design.",example:"Test 15%, 15.01%, same HRBP, changed employer and HRBP initiation.",check:shared("Best threshold test for >15%?",["18% only","15% and 15.01%","10% only"],1,"Boundary tests prove the operator behaves correctly.")}
 ]},
 {id:"absence",label:"ABS",title:"Absence Management",sub:"Configure plans, types, eligibility, accruals, certifications, approvals and testing.",time:"4 hrs",color:"green",status:"AVAILABLE",lessons:[
  {stage:"FOUNDATIONS",title:"How Absence Management fits together",time:"20 min",objective:"Understand the relationship between absence types, plans, balances and worker records.",topics:["Absence type = what the worker records","Absence plan = entitlement and balance rules","Plan enrolment connects worker to entitlement","Absence entry consumes or records time","Legislation and payroll dependencies"],judgement:"Start from the business policy and worker population; never begin by copying an existing plan.",example:"An employee requests Annual Leave through the Annual Leave type; the request consumes days from the UK Annual Leave plan.",check:shared("Which component normally holds the worker’s entitlement and balance rules?",["Absence type","Absence plan","Absence reason"],1,"The plan governs entitlement and balance behaviour; the type is used to record the absence.")},
  {stage:"RECORDING",title:"Types, categories and reasons",time:"25 min",objective:"Design how employees record and classify an absence.",topics:["Absence categories","Absence type attributes","Reasons and reason requirements","Units: days or hours","Partial-day behaviour","Display and self-service settings"],judgement:"Use reasons for meaningful analysis or downstream rules—not to create an unnecessarily long list.",example:"Sickness is the type; Medical Appointment and Viral Illness are optional reasons; the UK Sick plan tracks entitlement separately.",check:shared("What is the best use of an absence reason?",["Replace the absence type","Capture useful detail beneath a type","Store the accrual rate"],1,"A reason classifies why the selected absence type was used.")},
  {stage:"ENTITLEMENT",title:"Accrual and qualification plans",time:"30 min",objective:"Choose the correct plan design for accrued or qualified entitlement.",topics:["Accrual plan","Qualification plan","No-entitlement recording","Calendar-year vs anniversary term","Plan units and balance display","Payroll integration considerations"],judgement:"Choose the plan type that reflects the policy; not every absence requires an accruing balance.",example:"Annual Leave accrues throughout the year; Occupational Sick Pay may qualify workers for bands of paid entitlement based on service.",check:shared("A policy grants paid sick entitlement based on length of service rather than a growing leave balance. Best starting point?",["Qualification plan","Accrual plan only","Absence reason"],0,"Qualification plans support entitlement bands and qualification rules.")},
  {stage:"ELIGIBILITY",title:"Eligibility and enrolment",time:"25 min",objective:"Control who can join a plan and when participation begins or ends.",topics:["Eligibility profiles","Employment and assignment criteria","Automatic vs manual enrolment","Enrolment start rules","Waiting periods","Loss of eligibility and termination"],judgement:"Eligibility answers who qualifies; enrolment rules answer when their plan participation begins.",example:"UK permanent employees enrol automatically on hire; contractors and India employees are excluded by eligibility.",check:shared("A worker meets the profile today but entitlement begins after three months. Which two ideas are involved?",["Reason and category","Eligibility and waiting period","Ceiling and carryover"],1,"The profile selects the population; the waiting period delays participation or use.")},
  {stage:"ACCRUALS",title:"Accrual rates, bands and proration",time:"35 min",objective:"Configure how entitlement is earned for different workers and partial periods.",topics:["Accrual frequency","Flat and service-based rates","Accrual bands","New-hire proration","FTE or work-schedule proration","Mid-period changes","Partial-period rules"],judgement:"Write worked calculations for at least three workers before configuring the matrix.",example:"A full-time worker receives 25 days; a 0.6 FTE worker receives 15 days; a July joiner receives the policy-defined partial-year amount.",check:shared("What is the strongest way to validate an accrual matrix?",["Confirm the plan saves","Calculate expected balances for representative workers","Test one full-time worker only"],1,"Worked examples prove rates, bands and proration across the population.")},
  {stage:"LIMITS",title:"Ceilings, carryover and expiry",time:"30 min",objective:"Control how much can accumulate and what happens at term end.",topics:["Accrual ceiling","Carryover limit","Carryover expiry","Residual balance rules","Front-loaded vs periodic accrual","Negative balance considerations"],judgement:"Ceiling and carryover solve different questions: maximum balance during the term versus balance moved into the next term.",example:"A worker can hold no more than 30 days during the year, carry 5 into next year, and must use those 5 by 31 March.",check:shared("A plan allows 5 unused days to move into next year. Which rule is this?",["Ceiling","Carryover","Waiting period"],1,"Carryover determines the balance transferred between plan terms.")},
  {stage:"CONTROLS",title:"Waiting, vesting and entry validation",time:"25 min",objective:"Apply policy controls to entitlement availability and absence entry.",topics:["Waiting period","Vesting period","Advance notice","Maximum duration","Minimum duration","Open-ended absence","Overlapping and consecutive entries"],judgement:"Distinguish earning entitlement from being allowed to use it; poorly chosen controls create false balances or blocked requests.",example:"A new hire starts accruing on day one but cannot use the accrued leave until completing three months—this is vesting.",check:shared("A worker earns leave immediately but cannot use it for 90 days. What is this?",["Vesting restriction","Carryover expiry","Qualification band"],0,"Vesting delays use of earned entitlement.")},
  {stage:"EVIDENCE",title:"Certifications and documentation",time:"25 min",objective:"Request and track evidence based on absence duration or event.",topics:["Certification requirements","Trigger timing","Employee and manager actions","Document status","Follow-up and overdue handling","Certification-related notifications"],judgement:"Certification design must state what happens when evidence is missing; requesting a document is not itself an escalation strategy.",example:"A fit note is required after seven calendar days of sickness; the request is created on day eight and HR follows overdue evidence.",check:shared("A certificate is missing after day seven. What must the requirement clarify?",["Only the field colour","Trigger, responsible actor and consequence","The annual-leave ceiling"],1,"Evidence rules need operational ownership and a defined outcome.")},
  {stage:"OPERATIONS",title:"Balances, adjustments and scheduled processes",time:"25 min",objective:"Maintain balances safely and understand routine processing.",topics:["Balance calculation","Manual adjustments","Adjustment reasons and audit","Accrual processing","Evaluate absences","Update balances","Reconciliation and troubleshooting"],judgement:"Use adjustments for authorised corrections with evidence—not to compensate for misunderstood configuration.",example:"HR adds two days awarded through a service recognition policy using an adjustment reason and retains approval evidence.",check:shared("A balance is wrong for many workers after year-end. Best first response?",["Manually adjust everyone","Investigate plan rules and processing","Delete the plan"],1,"A population-wide issue usually indicates configuration or processing, not individual corrections.")},
  {stage:"DELIVERY",title:"Approvals, reporting and end-to-end testing",time:"40 min",objective:"Complete the functional design across workflow, analytics and regression.",topics:["Manager and conditional approvals","Self-approval and missing approver handling","Notifications","Balance and absence reporting","HDL considerations","Positive, negative and boundary tests","Quarterly regression"],judgement:"An absence design is complete only when entitlement, entry, approval, evidence, processing and reporting reconcile.",example:"Test a 5-day sick absence, an 8-day absence requiring a certificate, a retrospective entry, an extension, approval and final report output.",check:shared("Which test gives the best end-to-end assurance?",["The type appears in self-service","Request → approval → balance/evidence → report reconciliation","The plan name is correct"],1,"The full transaction lifecycle proves the connected design.")}
 ]},
 {id:"journeys",label:"JRN",title:"Checklists and Journeys",sub:"Design client onboarding, offboarding and workforce-process experiences with governed tasks.",time:"4 hrs",color:"violet",status:"AVAILABLE",lessons:[
  {stage:"FOUNDATIONS",title:"Checklist, journey and allocated journey",time:"20 min",objective:"Understand the template-to-worker lifecycle and current Oracle terminology.",topics:["Journey/checklist template","Assigned or allocated journey","Allocated task","Template vs worker instance","Onboarding, offboarding and personal journeys"],judgement:"Design the reusable template first; an allocated journey is the worker-specific copy that people complete.",example:"‘UK New Hire Journey’ is the template. When Maya is hired, Oracle allocates her own journey with dated tasks for Maya, her manager, IT and HR.",check:shared("What is the worker-specific instance created from a template?",["Journey category","Allocated journey/checklist","Eligibility profile"],1,"The allocated journey is the instance assigned to the worker.")},
  {stage:"DESIGN",title:"Categories, templates and ownership",time:"25 min",objective:"Organise journeys by purpose, owner and target population.",topics:["Journey categories","Template status and effective dates","Checklist purpose and scope","Enterprise vs personal journey","Template ownership","Duplication and version control"],judgement:"One template should serve one clear business outcome; avoid one enormous global checklist filled with exceptions.",example:"Use separate New Hire and Termination templates; localise tasks by eligibility instead of mixing offboarding into onboarding.",check:shared("Why use journey categories?",["To group and govern templates by purpose","To calculate salary","To create departments"],0,"Categories organise journey templates and can support access governance.")},
  {stage:"TASKS",title:"Task types and completion behaviour",time:"35 min",objective:"Choose task types that match the action the performer must complete.",topics:["Manual and external URL tasks","Document and questionnaire tasks","Video and embedded learning","Report and analytics tasks","Electronic signature where enabled","Application and advanced tasks","What marks each task complete"],judgement:"Choose a task type for the required user action and evidence—not for visual variety.",example:"‘Read the handbook’ uses Document; ‘confirm equipment received’ uses Questionnaire; ‘enter bank details’ links to the relevant application task.",check:shared("A worker must answer and submit several onboarding questions. Best task type?",["Questionnaire","Video","Manual task only"],0,"A questionnaire captures structured responses rather than a simple acknowledgement.")},
  {stage:"PEOPLE",title:"Task performers and responsibility",time:"25 min",objective:"Resolve the correct worker, manager, HR or named performer for every task.",topics:["Worker and line manager performers","Area of Responsibility and HR performers","Named user and external performer considerations","Performer at allocation time","Missing performer handling","Task owner vs performer"],judgement:"Every task must resolve to a real accountable performer for the target population before go-live.",example:"The worker uploads documents; the line manager agrees objectives; the IT Service Desk prepares equipment; HR verifies completion.",check:shared("What should be tested for every performer rule?",["Only the task colour","Resolution for representative workers and missing-person cases","The annual-leave balance"],1,"Performer resolution must succeed for the real population and fail safely.")},
  {stage:"TIMING",title:"Offsets, due dates and dependencies",time:"30 min",objective:"Sequence tasks around the journey allocation date and business milestones.",topics:["Before and after offsets","Due-date calculation","Task dependencies","Activation criteria","Parallel vs dependent work","Overdue and completion sequencing"],judgement:"Dates must reflect operational lead time; a laptop task due on day one may be too late for a new hire starting remotely.",example:"IT equipment is due five days before start; induction is due on day one; probation goals activate after induction completion.",check:shared("A task must become available only after another task completes. Use?",["Dependency","Category security","Reference data set"],0,"A dependency controls task sequence and availability.")},
  {stage:"ELIGIBILITY",title:"Eligibility and conditional tasks",time:"25 min",objective:"Show the right journey and tasks to the right worker population.",topics:["Journey-level eligibility","Task-level eligibility","Assignment and person criteria","Country, business unit and worker type","Exclusion rules","Eligibility evaluation timing"],judgement:"Use eligibility to separate genuine population differences; do not duplicate templates for one small conditional task.",example:"All UK new hires receive the journey, but only remote workers receive the Home Office Equipment task.",check:shared("A task applies only to remote workers within a common onboarding journey. Best design?",["Separate global template","Task-level eligibility","Manual deletion after allocation"],1,"Task-level eligibility applies the variation inside the shared journey.")},
  {stage:"ALLOCATION",title:"How journeys are assigned",time:"25 min",objective:"Select and test automatic, manual and bulk allocation approaches.",topics:["Automatic allocation from supported events","Manual allocation","Mass allocation","REST and HDL allocated-checklist options","Allocation date and person/assignment context","Duplicate allocation control"],judgement:"Choose the allocation method that reliably matches the business event and volume, then define rehire and duplicate behaviour.",example:"A hire event automatically assigns onboarding; HR manually assigns a Performance Improvement journey; a migration loads active journeys in bulk.",check:shared("Which question is essential for automatic allocation?",["What exact business event triggers it?","Which font is used?","What is the KFF delimiter?"],0,"Automatic allocation depends on a precise supported event and target context.")},
  {stage:"COMMUNICATION",title:"Notifications, nudges and escalations",time:"25 min",objective:"Keep tasks visible without overwhelming workers and managers.",topics:["Assignment notifications","Task reminders","Overdue notifications","Alerts-based notification options","Recipient and timing design","Escalation ownership","Notification content"],judgement:"A notification calendar should distinguish helpful reminders from noise and state who owns overdue action.",example:"Send assignment notice on hire, reminder two days before due date, overdue alert to performer, and manager escalation after five overdue days.",check:shared("What makes an overdue notification operationally useful?",["A clear action, owner and due context","Sending it every hour","No task link"],0,"The recipient needs to know what to do, for whom and by when.")},
  {stage:"GOVERNANCE",title:"Security, maintenance and allocated journeys",time:"30 min",objective:"Control who can create templates, view assignments and maintain worker journeys.",topics:["Category security","Template administration","Worker and manager access","HR person-security scope","Manage allocated journeys and tasks","Add, reassign or delete tasks","Impact of template changes on existing allocations"],judgement:"Test template administration separately from access to a worker’s allocated journey; these are different responsibilities.",example:"The Journey Designer can maintain onboarding templates, while the HR Specialist manages allocated journeys only for workers in their security population.",check:shared("Why must template changes be tested against existing allocations?",["All changes always rewrite allocations","Template-library and allocated behaviour can differ","It changes payroll automatically"],1,"Some changes apply only to future allocations or behave differently for already allocated tasks.")},
  {stage:"DELIVERY",title:"Reporting, integration and end-to-end testing",time:"35 min",objective:"Prove allocation, task execution, monitoring and closure across all actors.",topics:["Journey and task status reporting","Overdue and completion dashboards","Questionnaire/document evidence","REST and HDL allocation considerations","Task-group reuse","Quarterly regression","Support and troubleshooting"],judgement:"A journey is complete only when every persona, date, dependency, notification and reporting outcome is tested—not when the template merely becomes Active.",example:"Hire Maya, confirm automatic allocation, complete worker/manager/IT tasks in sequence, test reminders, verify status reporting and close the journey.",check:shared("Which is the strongest journey test?",["Template status is Active","End-to-end allocation through all performers and reports","One HR task is visible"],1,"End-to-end execution proves the full client process.")}
 ]},
 {id:"otbi",label:"OTBI",title:"OTBI Reporting Basics",sub:"Build accurate analyses from HCM subject areas and explain the resulting data.",time:"3 hrs",color:"blue",status:"AVAILABLE",lessons:[
  {stage:"FOUNDATIONS",title:"What OTBI is and when to use it",time:"25 min",objective:"Choose OTBI for interactive, secured transactional analysis.",topics:["Analysis, dashboard and agent","Subject areas","Real-time transactional reporting","OTBI vs BIP vs Extracts"],judgement:"Use OTBI when users need interactive analysis—not a highly formatted document or outbound interface.",example:"HR creates a dashboard of active workers by department and drills to employee detail.",check:shared("Best tool for an interactive headcount dashboard?",["OTBI","HDL","Fast Formula"],0,"OTBI is designed for secured interactive analysis.")},
  {stage:"DATA",title:"Subject areas, folders and grain",time:"35 min",objective:"Select columns without creating misleading counts or duplicates.",topics:["Facts and dimensions","Person vs assignment grain","Effective dates","Common and module subject areas"],judgement:"Define what one output row represents before choosing columns.",example:"One person with two assignments should count once for people but twice for assignments.",check:shared("Why can one employee appear twice?",["Multiple assignments at assignment grain","The font is wrong","A checklist exists"],0,"Assignment-level subject areas return assignment rows.")},
  {stage:"BUILD",title:"Filters, prompts, views and calculations",time:"40 min",objective:"Build a useful analysis with controlled user interaction.",topics:["Filters and prompted filters","Tables, pivots and charts","Calculated columns","Totals and conditional formatting"],judgement:"A chart is only useful after filters, grain and totals are proven in the underlying table.",example:"A dashboard prompt filters active-worker headcount by legal employer, business unit and department.",check:shared("What should be validated before charting?",["Row-level data and totals","Only chart colour","Journey category"],0,"The underlying dataset must be correct first.")},
  {stage:"SECURITY",title:"Effective dates, security and scheduled refreshes",time:"30 min",objective:"Explain why users see different data and why some dimensions need processes.",topics:["User data security","As-of-date logic","Manager hierarchy refresh","Subject-area prerequisites"],judgement:"Never treat an OTBI difference as a report defect until date context and user security are compared.",example:"An HRBP sees UK workers while an administrator sees all countries using the same analysis.",check:shared("Same report, different results by user. First checks?",["Security and date context","KFF delimiter","Accrual ceiling"],0,"OTBI respects HCM data security and time context.")},
  {stage:"DELIVERY",title:"Validate, publish and troubleshoot",time:"30 min",objective:"Reconcile results and release reports safely.",topics:["Catalog folders","Custom content","Reconciliation","Performance and duplicate-row troubleshooting"],judgement:"Reconcile a representative sample to the application before publishing any workforce metric.",example:"Validate ten workers in the UI, reconcile headcount totals and publish to a controlled Custom folder.",check:shared("What proves an OTBI report?",["A sample and total reconciliation","It runs without error","It has a logo"],0,"Reconciliation proves the business result.")}
 ]},
 {id:"alerts",label:"ALRT",title:"Alert Composer",sub:"Create timely operational notifications from HCM events and conditions.",time:"2.5 hrs",color:"coral",status:"AVAILABLE",lessons:[
  {stage:"FOUNDATIONS",title:"Alerts, approvals and OTBI agents",time:"25 min",objective:"Choose the correct notification mechanism.",topics:["Event and resource alerts","BPM notifications","OTBI agents","Journey reminders"],judgement:"Use Alert Composer for supported HCM event/resource notifications—not to replace approvals.",example:"Alert HR 30 days before a fixed-term contract ends; use BPM when a decision is required.",check:shared("A manager must approve a transfer. Use?",["BPM approval","Alert Composer only","OTBI chart"],0,"Approvals require decision workflow.")},
  {stage:"DESIGN",title:"Resource, trigger and condition",time:"30 min",objective:"Define exactly when and for whom an alert fires.",topics:["Business resource","Event or scheduled evaluation","Filter conditions","Effective dates"],judgement:"Write the trigger in plain language with a worked record before configuration.",example:"Every day, find active employees whose contract end date is exactly 30 days away.",check:shared("What prevents broad unwanted alerts?",["Precise trigger and filter","More recipients","Longer subject line"],0,"The population condition controls scope.")},
  {stage:"PEOPLE",title:"Recipients and message tokens",time:"30 min",objective:"Resolve recipients and create actionable content.",topics:["Worker and manager","HR/AOR recipients","Tokens","Deep links and sensitive data"],judgement:"Confirm every recipient resolves for representative workers and expose only necessary personal data.",example:"Send the worker name and contract date to manager and HRBP with a link to the assignment.",check:shared("What must be tested for HRBP recipients?",["AOR resolution and missing AOR","Leave carryover","Tree flattening only"],0,"Representative resolution is essential.")},
  {stage:"OPERATE",title:"Frequency, suppression and escalation",time:"25 min",objective:"Avoid duplicates and notification fatigue.",topics:["Scheduling","Repeat frequency","Duplicate suppression","Escalation ownership"],judgement:"Every recurring alert needs a stop condition and owner.",example:"Notify at 30 and 7 days, then stop after extension or termination.",check:shared("What prevents endless reminders?",["Stop condition","More tokens","A grade ladder"],0,"The alert must know when the issue is resolved.")},
  {stage:"DELIVERY",title:"Testing and troubleshooting alerts",time:"25 min",objective:"Prove trigger, recipients, content and delivery.",topics:["Test population","Boundary dates","Delivery channels","Logs and support evidence"],judgement:"Test one record that should fire and one nearly identical record that should not.",example:"Test contracts ending in 30 versus 31 days and compare recipient delivery.",check:shared("Best boundary test for 30-day alert?",["30 and 31 days","One 10-day record","No test data"],0,"Adjacent values prove the condition.")}
 ]},
 {id:"hdl",label:"HDL",title:"HDL and HSDL",sub:"Load and maintain HCM data safely with keys, effective dates and reconciliation.",time:"4 hrs",color:"green",status:"AVAILABLE",lessons:[
  {stage:"FOUNDATIONS",title:"HDL, HSDL and business objects",time:"30 min",objective:"Choose file or spreadsheet loading for the right audience and volume.",topics:["HDL files","HSDL templates","Business objects/components","Inbound use cases"],judgement:"HSDL is controlled business-user loading; HDL is the broader file-based loader.",example:"HR uses a restricted HSDL salary template; conversion uses HDL worker files.",check:shared("Best controlled spreadsheet for HR specialists?",["HSDL","OTBI","Alert Composer"],0,"HSDL exposes governed spreadsheet loading.")},
  {stage:"KEYS",title:"Source keys, user keys and references",time:"35 min",objective:"Identify and maintain records reliably.",topics:["Source system owner/id","User keys","Surrogate IDs","Parent-child references"],judgement:"Prefer stable source keys for converted and integrated data.",example:"LEGACY/EMP1001 remains stable even if the employee’s person number changes.",check:shared("Which key is designed to remain stable from the source?",["Source key","Display name","Department name"],0,"Source keys uniquely identify source records.")},
  {stage:"DATES",title:"Date-effective loading and modes",time:"40 min",objective:"Create, update and correct history without damaging future rows.",topics:["Effective start/end","UPDATE and CORRECTION","Replace/retain future changes","Multiple changes per day"],judgement:"Draw expected history before loading a date-effective object.",example:"Correct a wrong 1 June department or create a genuine transfer from 1 September.",check:shared("Wrong historical value with no real change?",["Correction","New update","Delete worker"],0,"Correction fixes an existing history row.")},
  {stage:"BUILD",title:"File structure, load and errors",time:"40 min",objective:"Prepare, submit and diagnose a load.",topics:["METADATA/MERGE lines","ZIP and upload","Import/load phases","Error messages"],judgement:"Fix the smallest failing component and reload using the same keys.",example:"A location load fails because the set code is invalid; correct reference data and reload.",check:shared("Why retain the same source key on retry?",["To update the same record","To create duplicates","To change security"],0,"Stable keys prevent duplicate creation.")},
  {stage:"DELIVERY",title:"Templates, security and reconciliation",time:"35 min",objective:"Release safe loads to business users.",topics:["HSDL column control","Template access","Validation","Post-load reconciliation"],judgement:"A successful load status is not proof; reconcile counts and critical attributes.",example:"Load 100 locations, reconcile 100 successes, countries, sets and effective dates.",check:shared("What completes a data load?",["Reconciliation","File upload only","A green button"],0,"Loaded data must be verified.")}
 ]},
 {id:"formula",label:"FF",title:"Fast Formula Fundamentals",sub:"Read, test and design simple HCM formulas without turning trainees into developers.",time:"3 hrs",color:"violet",status:"AVAILABLE",lessons:[
  {stage:"FOUNDATIONS",title:"What Fast Formula does",time:"25 min",objective:"Recognise formula use cases and boundaries.",topics:["Formula types","Business rules/calculations","Module context","When standard configuration is enough"],judgement:"Use formula only when standard configuration cannot express the rule clearly.",example:"Calculate absence entitlement based on FTE and service when the standard matrix is insufficient.",check:shared("First design question?",["Can standard configuration meet it?","Which font?","Which chart?"],0,"Avoid unnecessary custom logic.")},
  {stage:"LANGUAGE",title:"Inputs, defaults and return values",time:"35 min",objective:"Read and write a small deterministic formula.",topics:["INPUTS ARE","DEFAULT FOR","IF/THEN/ELSE","Return variables"],judgement:"Document every input and return value in business language.",example:"Input FTE; return annual entitlement of 25 × FTE.",check:shared("What does a formula return to its caller?",["Defined return value","A journey category","A department tree"],0,"The formula contract specifies outputs.")},
  {stage:"DATA",title:"Contexts and database items",time:"35 min",objective:"Understand how the formula receives transaction and person data.",topics:["Formula contexts","Database items","Data types","Null/default handling"],judgement:"Never assume a database item is available in every formula type.",example:"An absence formula uses person/assignment context to read service date and FTE.",check:shared("Why compile in the correct formula type?",["Available contexts and returns differ","Colour changes","OTBI refreshes"],0,"Formula type defines the contract.")},
  {stage:"TEST",title:"Compile, test and troubleshoot",time:"30 min",objective:"Diagnose syntax, data and boundary failures.",topics:["Compilation","Test inputs","Logs/errors","Boundary cases"],judgement:"Test zero, null, exact-threshold and above-threshold cases.",example:"Validate service values of 2.99, 3 and 3.01 years for an entitlement band.",check:shared("Best band boundary test?",["Below, equal and above","One random value","No inputs"],0,"Boundary tests prove operators.")},
  {stage:"GOVERN",title:"Documentation and supportability",time:"25 min",objective:"Keep formulas readable and owned.",topics:["Naming/comments","Version control","Dependency register","Regression"],judgement:"A clever formula nobody can support is a poor functional design.",example:"Record purpose, owner, calling plan, inputs, returns and five test examples.",check:shared("Essential handover?",["Formula contract and tests","Only formula name","Screenshot alone"],0,"Support needs purpose and evidence.")}
 ]},
 {id:"schedules",label:"SCH",title:"Shifts, Patterns and Work Schedules",sub:"Model when people work and understand the impact on absence and time calculations.",time:"3 hrs",color:"blue",status:"AVAILABLE",lessons:[
  {stage:"FOUNDATIONS",title:"Shift, pattern and schedule",time:"30 min",objective:"Distinguish the three layers.",topics:["Shift = one work period","Pattern = repeating shifts","Schedule = dated application","Calendar events"],judgement:"Start with the worker’s repeating timetable, not with system terminology.",example:"9–5 is a shift; Mon–Fri is a pattern; UK Office 2026 is the dated schedule.",check:shared("A repeating Mon–Fri sequence is?",["Pattern","Location","Grade"],0,"Patterns repeat shifts.")},
  {stage:"BUILD",title:"Create shifts and patterns",time:"35 min",objective:"Model full-time, part-time and overnight work.",topics:["Start/end times","Duration","Non-working days","Overnight shifts"],judgement:"Use representative rosters and verify total weekly hours.",example:"Nurse pattern: two day shifts, two night shifts, four rest days.",check:shared("What must be reconciled?",["Pattern hours to policy","OTBI logo","KFF delimiter"],0,"Scheduled hours must match working policy.")},
  {stage:"ASSIGN",title:"Schedule assignment and hierarchy",time:"30 min",objective:"Apply schedules at the correct level and effective date.",topics:["Person/assignment schedule","Employment-level defaults","Start/end dates","Overrides"],judgement:"Document which level wins when more than one schedule is available.",example:"Most UK staff inherit office schedule; Jenny receives a part-time assignment override.",check:shared("A worker has a personal override. What matters?",["Schedule hierarchy","Journey category","Source owner"],0,"Hierarchy determines the applied schedule.")},
  {stage:"IMPACT",title:"Absence duration and calendar events",time:"35 min",objective:"Explain how schedules influence working duration.",topics:["Working vs elapsed days","Hours/day conversion","Public holidays","Partial day"],judgement:"Test absence across weekends, holidays and non-working days.",example:"Friday-to-Monday leave consumes two days for Mon–Fri staff, subject to policy and calendar.",check:shared("Why test a public holiday?",["It can change calculated duration","It changes grade","It allocates a journey"],0,"Calendars affect working time.")},
  {stage:"DELIVERY",title:"Changes, loading and troubleshooting",time:"30 min",objective:"Maintain schedules without corrupting history.",topics:["Future schedule changes","HDL assignment","Missing schedule","Regression"],judgement:"Future-date roster changes and test connected absence/time behaviour.",example:"Move a worker to four-day week next month and validate absence duration before and after.",check:shared("Best effective-date test?",["Before and after schedule change","One date only","No worker"],0,"Both periods must behave correctly.")}
 ]},
 {id:"operations",label:"OPS",title:"Processes, Audit and Troubleshooting",sub:"Operate Oracle HCM, investigate failures and collect evidence for support.",time:"3 hrs",color:"green",status:"AVAILABLE",lessons:[
  {stage:"PROCESSES",title:"Scheduled processes",time:"30 min",objective:"Submit, monitor and interpret routine HCM processing.",topics:["Process parameters","Schedules","Parent/child jobs","Logs/output"],judgement:"Understand business effect before rerunning a failed process.",example:"Run Calculate Accruals and Balances for a defined population and reconcile output.",check:shared("Before rerun?",["Understand parameters and impact","Click repeatedly","Delete output"],0,"Reruns can duplicate or change results.")},
  {stage:"AUDIT",title:"HCM audit basics",time:"30 min",objective:"Trace who changed configured or transactional data.",topics:["Audit policies","Audit reports","Old/new values","User and timestamp"],judgement:"Enable only governed audit areas and protect audit access.",example:"Identify who changed a worker’s department and when.",check:shared("Audit answers?",["Who changed what and when","Future headcount only","Journey colour"],0,"Audit records change evidence.")},
  {stage:"TRANSACTIONS",title:"Transaction Console and workflow failures",time:"35 min",objective:"Diagnose stuck or failed transactions safely.",topics:["Transaction status","Assignees","Errors","Recover/terminate decisions"],judgement:"Preserve evidence and understand business state before recovery.",example:"A transfer is stuck because an approver cannot resolve; correct setup and recover appropriately.",check:shared("First action on failed transaction?",["Capture status/error and diagnose","Delete employee","Rerun all processes"],0,"Evidence guides safe resolution.")},
  {stage:"METHOD",title:"Structured troubleshooting",time:"30 min",objective:"Separate data, setup, security and process causes.",topics:["Reproduce","Compare working/non-working","Logs","Recent changes"],judgement:"Change one variable at a time and record evidence.",example:"One worker cannot request leave; compare plan enrolment, eligibility, schedule and role with a working worker.",check:shared("Best comparator?",["Nearly identical working case","Random module","Screenshot colour"],0,"Comparison isolates the difference.")},
  {stage:"SUPPORT",title:"Oracle SR and operational handover",time:"25 min",objective:"Raise useful support cases and document recurring operations.",topics:["Business impact","Reproduction steps","Environment/version","Logs and diagnostics"],judgement:"An SR should contain evidence, not only ‘it does not work’.",example:"Provide pod, release, worker example, timestamp, steps, screenshots and logs.",check:shared("What speeds support?",["Reproducible evidence","More urgency words","No examples"],0,"Precise evidence enables diagnosis.")}
 ]},
 {id:"redwood",label:"RW",title:"Redwood and VB Studio Awareness",sub:"Understand modern HCM pages and configure supported business rules safely.",time:"2.5 hrs",color:"coral",status:"AVAILABLE",lessons:[
  {stage:"FOUNDATIONS",title:"Classic, responsive and Redwood",time:"25 min",objective:"Recognise page technologies and change impact.",topics:["Redwood UX","Page availability","Quarterly adoption","Regression"],judgement:"Confirm the actual page technology before proposing a personalisation.",example:"A rule built for an older responsive page may not control the new Redwood page.",check:shared("First check before page change?",["Page technology and support","Grade ladder","Accrual band"],0,"Configuration options differ.")},
  {stage:"TOOLS",title:"VB Studio and Express mode",time:"30 min",objective:"Understand where supported page rules are configured.",topics:["Edit Page in Visual Builder Studio","Workspace/sandbox concepts","Express mode","Publish lifecycle"],judgement:"Use the least complex supported tool that meets the requirement.",example:"Hide a field for employees but retain it for HR using a business rule.",check:shared("Where are many Redwood page rules configured?",["VB Studio","OTBI pivot","HDL file"],0,"Redwood extensions use VB Studio capabilities.")},
  {stage:"RULES",title:"Visible, required and read-only rules",time:"35 min",objective:"Translate policy into testable page behaviour.",topics:["Conditions","Role/country/action criteria","Required/read-only","Defaulting awareness"],judgement:"A UI-required field is not always a backend or HDL validation.",example:"Make Transfer Reason required on the Redwood transfer page for UK HR.",check:shared("What must also be tested?",["HDL/API behaviour separately","Only screen colour","Tree version"],0,"UI rules may not govern other channels.")},
  {stage:"GOVERN",title:"Extensions, conflicts and lifecycle",time:"30 min",objective:"Manage changes across environments and releases.",topics:["Naming/ownership","Migration","Rule priority","Quarterly regression"],judgement:"Register every extension with page, condition, owner and test cases.",example:"Two rules target the same field; document precedence and combined outcomes.",check:shared("Why keep extension register?",["Impact and regression control","Accrual calculation","Role provisioning"],0,"Changes need traceability.")},
  {stage:"DELIVERY",title:"Testing across roles and channels",time:"25 min",objective:"Prove intended UX without blocking operations.",topics:["Persona testing","Country/action variants","Accessibility","Fallback/support"],judgement:"Test the most restricted and most privileged personas.",example:"Employee cannot edit, manager can view, HR can update; HDL remains unaffected.",check:shared("Best persona coverage?",["Employee, manager and HR","HR only","No role differences"],0,"Role-specific rules require each persona.")}
 ]},
 {id:"bip",label:"BIP",title:"BI Publisher and HCM Extracts",sub:"Create formatted outputs and scheduled outbound HCM files with functional control.",time:"4 hrs",color:"violet",status:"AVAILABLE",lessons:[
  {stage:"CHOICE",title:"OTBI, BIP or Extracts?",time:"25 min",objective:"Choose the reporting or outbound tool by purpose.",topics:["Interactive analysis","Formatted documents","Scheduled outbound files","Volume"],judgement:"Choose by consumer, format, schedule and delivery—not familiarity.",example:"Dashboard = OTBI; employment letter = BIP; payroll vendor file = Extracts.",check:shared("Third-party outbound file?",["HCM Extracts","OTBI chart","Alert only"],0,"Extracts supports outbound delivery.")},
  {stage:"BIP",title:"BI Publisher fundamentals",time:"40 min",objective:"Understand data models, templates and reports.",topics:["Data model","Parameters","RTF/layout template","Catalog"],judgement:"Keep custom content in governed Custom folders.",example:"Create a parameterised employment confirmation letter with worker data.",check:shared("What formats the output?",["Layout template","Security profile","Shift pattern"],0,"Templates control document layout.")},
  {stage:"EXTRACT",title:"Extract data groups and records",time:"45 min",objective:"Model hierarchical outbound data.",topics:["Root/child data groups","Records/attributes","Parameters","Fast Formula usage"],judgement:"Sketch one output row and hierarchy before building data groups.",example:"One worker root with assignment and contact child records for a vendor file.",check:shared("Why link data groups?",["To form hierarchy","To create grades","To approve transfer"],0,"Links relate parent and child data.")},
  {stage:"DELIVERY",title:"Delivery, scheduling and formatting",time:"35 min",objective:"Send the right format to the right destination.",topics:["CSV/XML/PDF","BI Publisher templates","Delivery options","Scheduling"],judgement:"Define file naming, encryption, destination and failure ownership.",example:"Send encrypted weekly CSV to benefits provider and retain delivery log.",check:shared("Operational requirement?",["Failure owner and reconciliation","Chart colour","Journey category"],0,"Interfaces need monitored delivery.")},
  {stage:"TEST",title:"Validation and reconciliation",time:"30 min",objective:"Prove population, fields, format and delivery.",topics:["Extract validation","Sample records","Counts/control totals","Error handling"],judgement:"A delivered file is not correct until source-to-output totals and critical values reconcile.",example:"Reconcile 1,245 eligible workers, legal-employer counts and sample salaries.",check:shared("Best proof?",["Control totals and samples","File exists","Template opens"],0,"Data accuracy needs reconciliation.")}
 ]},
 {id:"security",label:"SEC",title:"Security and Areas of Responsibility",sub:"Understand everyday role access and AORs without expecting trainees to architect enterprise security.",time:"3 hrs",color:"grey",status:"FINAL BASICS",lessons:[
  {stage:"FOUNDATIONS",title:"Roles and inheritance",time:"30 min",objective:"Explain abstract, job, duty and data roles at a functional level.",topics:["Abstract roles","Job roles","Duty roles","Data roles"],judgement:"Separate what a user can do from whose data they can do it to.",example:"HR Specialist job role gives functions; UK HR Specialist data role limits population.",check:shared("What usually combines job access with population?",["Data role","Absence reason","OTBI prompt"],0,"Data roles connect function and scope.")},
  {stage:"PROFILES",title:"Security profiles and data scope",time:"35 min",objective:"Recognise person, organisation, position and legislative scopes.",topics:["Person security profile","Organisation/position profiles","LDG/payroll scope","Data role mapping"],judgement:"Test access with named in-scope and out-of-scope workers.",example:"UK HR can view UK legal-employer workers but not India workers.",check:shared("Strongest security test?",["Positive and negative population","One admin user","No sample worker"],0,"Least privilege needs both sides.")},
  {stage:"AOR",title:"Areas of Responsibility",time:"35 min",objective:"Configure representative responsibility by scope.",topics:["Responsibility type","Scope by organisation/location/population","Start/end dates","Usage in approvals/journeys"],judgement:"AOR scope should match real accountability and resolve reliably.",example:"HRBP Maya covers UK Technology departments from 1 January.",check:shared("Why test AOR in approvals?",["Recipient resolution","Accrual ceiling","BIP layout"],0,"AORs often resolve HR representatives.")},
  {stage:"PROVISION",title:"Role provisioning basics",time:"30 min",objective:"Understand automatic and manual role assignment.",topics:["Role mappings","Conditions","Autoprovision/deprovision","User account timing"],judgement:"Every automatic role needs clear eligibility and removal behaviour.",example:"Active employees receive Employee role; HR job code receives HR Specialist data role.",check:shared("What happens on lost eligibility?",["Deprovision behaviour must be defined","Nothing ever","Tree flattens"],0,"Access should end appropriately.")},
  {stage:"TROUBLESHOOT",title:"Basic security diagnosis",time:"25 min",objective:"Investigate missing or excessive access methodically.",topics:["Role assignment","Role inheritance","Data role/profile","Security refresh processes"],judgement:"Compare the failing user with a working user and identify function versus data scope.",example:"HR can open Person Management but cannot find Jenny: check population security, not only menu privileges.",check:shared("Page opens but worker missing. Likely area?",["Data security scope","Page colour","Alert frequency"],0,"Function exists; population may be excluded.")}
 ]},
 {id:"orc",label:"ORC",title:"Oracle Recruiting Cloud",sub:"Design the recruiting journey from requisition and sourcing through selection, offer and the handoff into Core HR.",time:"6 hrs",color:"coral",status:"AVAILABLE",lessons:[
  {stage:"ARCHITECTURE",title:"ORC architecture and recruiting terminology",time:"45 min",objective:"Explain the ORC object model and candidate journey before attempting setup.",topics:["Job requisition = approved demand to recruit for one or more openings","Candidate = an external prospect or internal employee being considered","Candidate submission = the candidate’s application to a specific requisition","Candidate selection process = phases and states controlling progress","Career site = candidate-facing place to search and apply","Job offer = proposed employment terms before worker creation","Hiring team = recruiter, hiring manager and collaborators","Core HR handoff = conversion of an accepted candidate into person, work relationship and assignment records"],judgement:"Keep Candidate and Candidate Submission separate. One person can apply to several requisitions, and each submission follows its own selection process.",example:"Meera has one candidate profile but applies for HR Analyst and Reporting Analyst. ORC creates two submissions with different recruiters, interviews and outcomes.",check:shared("What tracks Meera’s progress for one vacancy?",["Candidate submission","Person record","Department tree"],0,"The submission connects the candidate to a particular requisition and selection process.")},
  {stage:"FOUNDATION",title:"Recruiting enterprise and common setup",time:"45 min",objective:"Identify the shared structures and recruiting setup that drive downstream behaviour.",topics:["Legal employer, business unit, department, job, position, grade and location","Recruiting organisation and requisition templates","Candidate selection processes, phases and states","Requisition and candidate flexfields","Recruiting content library, questionnaires and interview questionnaires","Recruiting categories and career-site geography","Recruiting users, agents and hiring-team roles","Effective dates, ownership and configuration governance"],judgement:"Do not repair weak enterprise structures inside recruiting. ORC consumes Core HR structures, so incorrect jobs, positions or locations must be corrected at source.",example:"A UK HR Analyst position supplies legal employer, department, job, grade and location defaults to the requisition; the recruiter validates them instead of retyping free text.",check:shared("Where should an incorrect department normally be corrected?",["In the source enterprise structure","In every candidate profile","In the offer letter only"],0,"ORC relies on governed Core HR structures.")},
  {stage:"REQUISITION",title:"Create, approve and manage requisitions",time:"50 min",objective:"Translate workforce demand into a controlled, approvable requisition.",topics:["Standard, pipeline and evergreen requisition concepts","Job-based versus position-based recruiting","Openings, hiring managers, recruiters and collaborators","Requisition templates and defaulting","Internal and external descriptions","Prescreening questions and disqualification rules","Requisition approval and posting readiness","Suspension, cancellation, fill and audit history"],judgement:"Start with the workforce demand and hiring model. A requisition should not be used to hide an unapproved position or unclear headcount requirement.",example:"CHC creates a position-based requisition for two HR Analysts. Finance approves the headcount, HR validates the grade and the recruiter owns sourcing after approval.",check:shared("What must be clear before creating a requisition?",["Approved demand, openings and hiring structure","Candidate interview score","Payroll result"],0,"The requisition represents approved recruiting demand.")},
  {stage:"SOURCE",title:"Career sites, job posting and sourcing",time:"45 min",objective:"Publish accurate opportunities to the right internal and external audiences.",topics:["Internal and external career sites","Career-site configuration and branding governance","Job posting schedules and unposting","Posting descriptions, locations and categories","Internal mobility and employee visibility","External job boards and campaign/source tracking","Candidate pools and prospects","Accessibility, privacy notice and mobile application testing"],judgement:"The candidate experience is part of the functional design. Test search, job detail, application and confirmation on mobile as well as desktop.",example:"The HR Analyst role is visible internally for seven days, then externally on the CHC career site and an approved job board with source tracking.",check:shared("What should be tested after posting?",["Search, job details and application as a candidate","Only the recruiter page","An absence accrual"],0,"A successful posting must work from the candidate’s perspective.")},
  {stage:"CANDIDATE",title:"Candidate application, screening and selection",time:"55 min",objective:"Configure a fair, traceable candidate journey through phases and states.",topics:["Candidate profile and application flow","Prescreening questions and knockout responses","Duplicate-candidate handling","Candidate pools and referrals","Selection-process phases and states","Move, reject, withdraw and revert actions","Reason codes and candidate communication","Data privacy, consent and retention"],judgement:"Automate only transparent screening rules that the business can defend. Always design manual review and exception handling.",example:"Applicants without mandatory work authorisation are routed according to an approved screening rule; borderline qualifications remain for recruiter review rather than automatic rejection.",check:shared("Why record rejection reasons consistently?",["Audit, communication and recruiting analysis","To create payroll balances","To change the legal employer"],0,"Governed reasons support fairness, reporting and candidate communication.")},
  {stage:"INTERVIEW",title:"Interviews, feedback and collaborative selection",time:"45 min",objective:"Design interview scheduling and evaluation without exposing unnecessary candidate information.",topics:["Interview schedule and interview participants","Recruiter and hiring-manager responsibilities","Interview questionnaires and rating scales","Panel feedback and submission deadlines","Candidate communication and rescheduling","Missing, conflicting or biased feedback","Selection decision and evidence","Sensitive notes and access boundaries"],judgement:"Use structured questions and evidence-based scoring. Free-form notes must never contain discriminatory or irrelevant personal judgments.",example:"Three panel members evaluate the same five competencies. The recruiter follows up on missing feedback before the hiring manager moves the selected candidate.",check:shared("What improves interview comparability?",["A structured questionnaire and common rating guidance","Different criteria for every candidate","Uncontrolled private notes"],0,"Consistent criteria support fair and explainable decisions.")},
  {stage:"OFFER",title:"Offers, approvals and candidate acceptance",time:"50 min",objective:"Create an accurate offer and control approvals, documents, negotiation and acceptance.",topics:["Offer team and offer creation","Salary, grade, proposed start date and assignment details","Offer approval routing","Offer letter templates and tokens","Candidate preview, acceptance and rejection","Offer revision and negotiation","Checks and contingencies","Withdrawal, expiry and audit history"],judgement:"Treat the offer as a controlled employment proposal. Reconcile every term that must later become Core HR or payroll data.",example:"Meera’s offer includes legal employer, job, grade, salary and proposed start date. A salary above the grade guideline routes for additional approval before release.",check:shared("What is essential before releasing an offer?",["Approved and reconciled employment terms","A completed payroll run","A learning specialization"],0,"The candidate must receive accurate, approved terms that can support hiring.")},
  {stage:"HIRE",title:"Move to HR, onboarding and Core HR handoff",time:"45 min",objective:"Convert the accepted candidate into the correct worker records and start downstream onboarding.",topics:["Accepted offer and Move to HR","Pending worker and employee hiring patterns","Duplicate-person matching","Person, work relationship and assignment creation","Hire-date and proposed-start-date reconciliation","Personal and legislative information completion","Journeys or onboarding allocation","Failed handoff, correction, rehire and no-show scenarios"],judgement:"The handoff is not complete when a button is clicked. Reconcile the resulting Core HR person, work relationship and assignment against the accepted offer.",example:"After Meera accepts, HR validates the pending worker, avoids a duplicate person record, completes the hire and confirms that the onboarding journey is allocated.",check:shared("What proves a successful ORC handoff?",["Correct Core HR worker and assignment records","Candidate status alone","A career-site colour change"],0,"The employment records must match the approved offer.")},
  {stage:"OPERATE",title:"ORC security, notifications, OTBI and operations",time:"45 min",objective:"Run recruiting safely with clear access, communications, reporting and support ownership.",topics:["Recruiter, hiring manager, collaborator, interviewer and candidate personas","Function and data access to requisitions and submissions","Candidate and hiring-team notifications","OTBI requisition, submission, source and time-to-hire grain","Sensitive candidate and diversity information","Recruiter workload and aging dashboards","Integration, scheduled process and career-site monitoring","Quarterly update regression, privacy retention and audit"],judgement:"A hiring manager should see the candidates and actions required for their requisitions—not the organisation’s entire candidate database.",example:"A manager views submissions for her requisitions, interviewers see only assigned interviews and recruiting leaders see governed funnel metrics reconciled to ORC administration.",check:shared("What is the strongest ORC access test?",["Users cannot see unrelated candidates or requisitions","All recruiters share one login","The career site has a logo"],0,"Candidate data requires tested least-privilege access.")}
 ]},
 {id:"learning",label:"LRN",title:"Oracle Learn",sub:"Build, assign, sequence, monitor and report workforce learning with clear administrator controls.",time:"5 hrs",color:"blue",status:"AVAILABLE",lessons:[
  {stage:"ARCHITECTURE",title:"Learning architecture and technical vocabulary",time:"40 min",objective:"Explain how Oracle Learning stores content, delivery choices, assignments and completion records before using the administrator pages.",topics:["Learning item = an object learners can discover or receive","Course = the reusable subject or learning definition","Offering = a specific self-paced or instructor-led delivery of a course","Activity = video, content, assessment, ILT event or another step inside an offering","Specialization = a structured programme containing courses or other learning items","Catalog = the searchable collection exposed to eligible learners","Learning assignment = the requirement or opportunity given to a learner","Learning record = the learner-specific status, dates and completion history","Learning initiative = rules that continuously assign learning to an eligible population","SCORM and HACP = packaged e-learning communication standards; verify the supported standard and behaviour before loading content"],judgement:"Draw Course → Offering → Activity separately from Learner → Assignment → Learning Record. Mixing the two chains produces poor requirements and misleading reports.",example:"‘Information Security’ is the course. ‘2026 Online Edition’ is its self-paced offering. The SCORM module and final quiz are activities. Jenny receives a required assignment and her learning record moves from Not Started to In Progress to Completed.",check:shared("What is the learner-specific requirement and due date attached to Jenny?",["Course definition","Learning assignment","Catalog"],1,"The course is shared content; the assignment connects that learning to Jenny with learner-specific status and dates.")},
  {stage:"ADMIN",title:"Become a Learn administrator safely",time:"35 min",objective:"Understand the functional access and data scope required to administer learning without assuming that one role gives unrestricted access.",topics:["My Client Groups → Learning administrator workspace","Learning Specialist or organisation-specific administrator job/data role","Function security: what pages and actions the administrator can use","Data security: which learners, business units or learning objects the administrator can manage","Catalog and content ownership","Instructor and resource administration where enabled","Positive and negative persona testing","Segregation between learning administration, security administration and learner self-service"],judgement:"Use the organisation’s approved data role and test its population. Do not give broad implementation or security-administrator access merely to let someone assign a course.",example:"Maya can create offerings and assign compliance learning to UK workers. She can search UK learners but cannot manage India learner records; the India Learning Administrator has a separate scope.",check:shared("A Learn administrator can open Learning pages but cannot find India learners. What should be checked?",["Only the course title","The administrator’s data role and learner population scope","The SCORM bookmark"],1,"Page access and learner data access are separate security questions.")},
  {stage:"CONTENT",title:"Create and publish courses, offerings and activities",time:"45 min",objective:"Build the correct learning hierarchy and expose it to the intended audience.",topics:["Define the course purpose, language, ownership and completion rules","Create self-paced or instructor-led offerings","Add and order offering activities","Configure enrolment, capacity, dates, instructors and resources where relevant","Set offering completion criteria","Use access groups or audience controls for catalog visibility","Preview, publish and test as a learner","Maintain versions and retire obsolete delivery choices"],judgement:"Create a new offering when the delivery changes; do not duplicate the entire course for every date, language or delivery method unless the business design requires it.",example:"The Data Privacy course has a self-paced UK offering and a monthly instructor-led offering. Both teach the same subject but have different activities, enrolment and completion rules.",check:shared("The same course will be delivered online and in a classroom. Best starting design?",["One course with different offerings","Two unrelated person records","One OTBI prompt"],0,"Offerings represent different delivery choices beneath the reusable course.")},
  {stage:"ASSIGN",title:"Assign learning in different ways",time:"50 min",objective:"Choose the assignment method that matches who initiates, population size, recurrence and governance.",topics:["Learner self-enrolment from the catalog","Manager recommendation or assignment where enabled by policy and role","Direct administrator assignment to selected learners","Mass assignment to an identified population","Learning initiatives for rule-based or recurring population assignment","HDL, REST or integration for governed bulk/connected use cases where supported","Required versus voluntary assignment","Assignment dates, due dates, priority and expiration","Withdrawal, exception and reassignment handling"],judgement:"Direct assignment suits a known one-off group; a learning initiative suits a changing population that must continue to receive the requirement automatically.",example:"Assign an urgent safety briefing directly to 25 named workers. Use an initiative for every active warehouse worker so new joiners also receive the annual course.",check:shared("New warehouse hires must automatically receive mandatory safety learning every month. Best fit?",["A one-time manual assignment list","A population-based learning initiative","A new legal employer"],1,"An initiative continually evaluates the population and creates assignments according to its rules.")},
  {stage:"SEQUENCE",title:"Build sequential learning",time:"40 min",objective:"Design a programme whose learners complete learning in a controlled order and understand where sequencing is enforced.",topics:["Specialization structure and sections","Required and optional learning items","Section and activity ordering","Prerequisites versus recommended learning","Completion criteria for each item and the overall programme","Due dates inherited or calculated at assignment","Handling prior completion and equivalent learning","Changes to a published programme and existing learner impact"],judgement:"Use enforced sequence only when dependency or risk justifies it. Unnecessary locking frustrates experienced learners and complicates exceptions.",example:"New managers complete People Policy Basics, then Managing Absence, then the practical assessment. The second item remains unavailable until the first completion is recognised.",check:shared("Where should three related courses with controlled progression normally be grouped?",["A specialization","A person DFF","A department tree"],0,"A specialization provides a structured learning programme and can organise controlled progression.")},
  {stage:"RECORDS",title:"Manage assignments and learning records",time:"35 min",objective:"Support the learner lifecycle after assignment rather than treating assignment creation as completion.",topics:["Not Started, In Progress, Completed, Withdrawn and other delivered statuses","Assignment and offering dates","Required and voluntary learning","Completion, override and correction controls","Waiver or exception governance","Recurring learning and renewal","Learner transcript and history","Audit evidence and administrator comments"],judgement:"A manual completion or override changes compliance evidence. Require an approved reason, source proof and an auditable operating procedure.",example:"Jenny completed equivalent external training. The administrator records the approved completion evidence rather than deleting the mandatory assignment from reports.",check:shared("What is the strongest control for a manual completion?",["No reason required","Approved evidence, reason and audit trail","Rename the course"],1,"Compliance history must show why and by whom the learner record was changed.")},
  {stage:"OTBI",title:"Learning OTBI and supervisor hierarchy",time:"45 min",objective:"Build an accurate manager view of assigned, completed and overdue learning and validate hierarchy behaviour.",topics:["Workforce Learning subject areas available in the current release","Assignment and learning-record grain","Course, offering, learner and completion dimensions","Required, voluntary, status and due-date filters","Line manager and supervisor hierarchy attributes","Manager level prompts and roll-up totals","Multiple assignments and multiple manager relationships","Data-role and OTBI row-security interaction","Reconcile totals with Learning administration pages"],judgement:"Define one report row before selecting columns. A learner with multiple learning assignments or work assignments can multiply rows if grain and supervisor filters are unclear.",example:"A director dashboard shows overdue mandatory learning for everyone beneath her supervisory hierarchy, while each line manager sees only their permitted organisation. Test a worker with two assignments before trusting the count.",check:shared("Why can one worker appear more than once in a Learning OTBI analysis?",["The logo is duplicated","The selected subject-area grain includes multiple learning or work assignments","The course has a description"],1,"Learning and workforce relationships can each create multiple rows; filters and grain must be explicit.")},
  {stage:"NOTIFY",title:"Remind and escalate incomplete mandatory learning",time:"40 min",objective:"Design notifications that improve completion without spamming learners or exposing inappropriate data.",topics:["Delivered learning assignment notifications","Initial assignment and enrolment communications","Due-soon and overdue reminder timing","Learner, line manager and learning administrator recipients","Supervisor-hierarchy escalation","Template tokens, links and secure wording","Repeat frequency and duplicate prevention","Stop conditions after completion, withdrawal or date change","Use Alert Composer or OTBI agents only when the delivered learning notification cannot satisfy the requirement","Delivery monitoring, bounced mail and operational ownership"],judgement:"Start with delivered Learn notifications. Add an alert or OTBI agent only for a proven gap, with one owner and a tested stop condition.",example:"Learners receive reminders 14 and 3 days before the due date. At 7 days overdue, the current line manager receives a consolidated exception notice. Completed, withdrawn and waived records are excluded.",check:shared("What prevents overdue reminders continuing after completion?",["A tested completion stop condition","A longer course title","A new business unit"],0,"The population condition must exclude records that no longer require action.")}
 ]},
 {id:"talent",label:"TAL",title:"Oracle Talent Management",sub:"Connect goals, performance, talent review, succession and career development into one governed talent cycle.",time:"5.5 hrs",color:"violet",status:"AVAILABLE",lessons:[
  {stage:"ARCHITECTURE",title:"Talent architecture and essential terminology",time:"40 min",objective:"Explain how Oracle Talent modules connect without treating them as one indistinguishable process.",topics:["Goal Management = create, align, approve and track performance or development goals","Performance Management = evaluate contribution through configurable review documents","Talent Review = calibrate workers using ratings, meetings and talent pools","Succession Management = identify candidates for jobs or positions and assess readiness","Career Development = explore careers, development goals and development plans","Profiles and content items = skills, competencies, qualifications and experience used across talent","Talent ratings = values such as performance, potential, impact of loss and risk of loss","Core HR remains the source of person, assignment, job, position, department and manager context"],judgement:"Begin with the business decision being made. A performance rating, talent-review placement and succession readiness are related but are not the same record.",example:"Jenny’s manager evaluates her annual contribution in Performance Management. Leaders later assess her potential in Talent Review and add her as a ready-in-two-years candidate for the HR Manager position in Succession Management.",check:shared("Where is Jenny’s actual promotion recorded?",["Core HR assignment transaction","Talent Review meeting","Goal plan"],0,"Talent supports the decision; Core HR records the employment change.")},
  {stage:"SETUP",title:"Common setup, profiles and rating models",time:"40 min",objective:"Recognise the shared reference data that makes talent processes consistent and reportable.",topics:["Rating models and rating levels","Competencies, skills and content sections","Person, job and position profiles","Eligibility profiles and participant populations","Review periods and common dates","Goal libraries and reusable content","Ownership, governance and effective dating","Impact of shared setup changes across modules"],judgement:"Reuse governed rating models and profile content where the business meaning is genuinely shared; do not create near-duplicates for each process.",example:"CHC uses one five-point Performance rating model across annual reviews and talent calibration, while Potential uses a separate three-point model with clearly defined behaviours.",check:shared("Why avoid duplicate rating models with the same meaning?",["They weaken consistency and reporting","They improve security automatically","They create payroll results"],0,"Shared definitions support comparable decisions and reliable analytics.")},
  {stage:"GOALS",title:"Goal plans, alignment and development goals",time:"40 min",objective:"Design goal processes with clear ownership, dates, measures and approval behaviour.",topics:["Performance versus development goals","Goal plans and review periods","Organisation, manager and worker goals","Goal alignment and cascading","Weights, measurements and target outcomes","Goal approval and change control","Eligibility and assignment context","Goal carry-forward, cancellation and audit"],judgement:"Every goal must be measurable and owned. Cascading a vague corporate statement produces administrative volume, not useful performance management.",example:"A service goal to reduce HR-case resolution time is cascaded to the HR Operations team. Jenny’s target, measure, weight and due date are specific to her role.",check:shared("Which field makes a goal testable?",["A measurable target or success criterion","A longer title","A catalog category"],0,"A clear measure allows employee and manager to assess achievement consistently.")},
  {stage:"PERFORMANCE",title:"Performance documents and evaluation flow",time:"50 min",objective:"Configure a practical review cycle and explain its sections, participants, ratings and approvals.",topics:["Performance templates and document periods","Eligibility and document creation","Competency, goal, questionnaire and overall-summary sections","Employee self-evaluation and manager evaluation","Participants and feedback","Section and overall calculations","Manager sharing, acknowledgement and completion","Transfer, manager change, cancellation and reopening"],judgement:"Draw the document state flow and ownership at every step before configuring tasks or notifications.",example:"Jenny completes her self-evaluation, her manager rates goals and competencies, a project lead supplies participant feedback, and the manager shares the final document for acknowledgement.",check:shared("What should be designed before notification timing?",["The document process flow and task owner","The colour of the rating icon","The payroll calendar"],0,"Notifications only work when events and ownership are understood.")},
  {stage:"REVIEW",title:"Talent review meetings and calibration",time:"45 min",objective:"Prepare a talent review meeting using reliable population, ratings and facilitation controls.",topics:["Review population and meeting ownership","Performance and potential ratings","Nine-box configuration and placement","Risk of loss, impact of loss and mobility","Talent pools and development actions","Data submission and meeting preparation","Calibration changes and audit trail","Sensitive-data access and post-meeting actions"],judgement:"A nine-box is a structured conversation aid, not an automatic promotion list. Define rating evidence and challenge bias before the meeting.",example:"The Technology leadership team reviews 40 eligible managers, calibrates Jenny from medium to high potential with evidence and assigns a development action rather than promising an immediate promotion.",check:shared("What is the nine-box primarily used for?",["A structured talent-calibration discussion","Calculating payroll","Creating a legal employer"],0,"It supports comparison and discussion using defined talent dimensions.")},
  {stage:"SUCCESSION",title:"Succession plans, candidates and readiness",time:"45 min",objective:"Build succession coverage for critical jobs or positions with transparent candidate decisions.",topics:["Incumbent, job-based and position-based plans","Plan owners and access","Internal and external candidates where supported","Readiness, ranking and candidate status","Emergency versus longer-term successors","Candidate development actions","Talent-pool relationship","Vacancy, incumbent change and plan maintenance"],judgement:"Succession is risk planning, not a confidential promise of promotion. Record evidence, readiness horizon and development gaps.",example:"The HR Director position has one emergency successor and two longer-term candidates. Jenny is ready in two years after completing payroll exposure and leading a regional project.",check:shared("What does ‘ready in two years’ represent?",["A readiness assessment, not a guaranteed promotion","A payroll frequency","An automatic hire date"],0,"Readiness guides planning but does not create an employment commitment.")},
  {stage:"CAREER",title:"Career development and internal growth",time:"40 min",objective:"Connect career preferences, development goals, profiles and learning to realistic internal mobility.",topics:["Career preferences and areas of interest","Development goals and development plans","Career statement and mobility preferences","Skills and competency gaps","Explore roles and career opportunities","Mentoring and development activities where enabled","Learning recommendations and linked development","Manager conversation and employee ownership"],judgement:"Growth is broader than promotion. A good plan can include deeper expertise, lateral movement, project exposure or preparation for a future role.",example:"Jenny targets HR Manager, compares her profile with the role, records two development goals and completes a leadership course plus a six-month project assignment.",check:shared("Which is a valid career-development outcome?",["Promotion, lateral move or deeper expertise","Only immediate promotion","Automatic salary increase"],0,"Career growth can take several forms and should match the employee’s plan.")},
  {stage:"OPERATE",title:"Talent security, notifications, OTBI and annual operation",time:"45 min",objective:"Operate the talent cycle with appropriate access, reminders, reporting, reconciliation and support.",topics:["Employee, manager, HR specialist, meeting facilitator and plan-owner personas","Sensitive ratings and succession-candidate access","Delivered notifications and reminder events","OTBI grain for goals, performance and succession","Supervisor hierarchy and effective-dated manager changes","Cycle dashboards and completion monitoring","Reconciliation between administration pages and reports","Quarterly update regression, audit and service ownership"],judgement:"Test the most sensitive negative-access case. A manager who can see the wrong succession candidate or talent rating creates a serious confidentiality failure.",example:"HR monitors overdue performance documents by manager hierarchy, while succession-plan details remain visible only to approved plan owners and talent administrators.",check:shared("What is the most important negative security test?",["An unauthorised manager cannot see sensitive talent data","A logo displays correctly","A learner can open a course"],0,"Talent information needs strict population and function controls.")}
 ]}
];
const curriculumModules=[...modules.filter(m=>m.id!=="security"),modules.find(m=>m.id==="security")!];

type TraineeTask={id:string;area:string;level:string;name:string;brief:string;requirements:string[];deliverables:string[];tests:string[];assessment:string};
type SavedProgress={itemId:string;status:string};
const oracleLinks={docs:"https://docs.oracle.com/en/cloud/saas/human-resources/",books:"https://docs.oracle.com/en/cloud/saas/human-resources/books.html",videos:"https://docs.oracle.com/en/cloud/saas/human-resources/videos.html",community:"https://community.oracle.com/customerconnect/categories/hcm-human-resources",connect:"https://community.oracle.com/customerconnect/",register:"https://community.oracle.com/customerconnect/kb/articles/34-step-by-step-instructions-to-register-has-oracle-account",connectVideo:"https://www.youtube.com/watch?v=wUSucDHSBMs"};
const topicLabel:Record<string,string>={dff:"Descriptive Flexfields",eff:"Extensible Flexfields",kff:"Key Flexfields",approvals:"HCM Approvals BPM",absence:"Absence Management",journeys:"Journeys Checklists",otbi:"OTBI HCM",alerts:"Alert Composer HCM",hdl:"HCM Data Loader HSDL",formula:"Fast Formula HCM",schedules:"Work Schedules HCM",operations:"HCM Scheduled Processes Audit",redwood:"HCM Redwood Visual Builder Studio",bip:"BI Publisher HCM Extracts",security:"HCM Security Areas of Responsibility",orc:"Oracle Recruiting Cloud requisitions candidates career sites offers hiring",learning:"Oracle Learn courses offerings assignments specializations",talent:"Oracle Talent Management goals performance talent review succession career development"};
function youtubeSearch(topic:string){return `https://www.youtube.com/results?search_query=${encodeURIComponent(`Oracle Fusion Cloud HCM ${topic}`)}`}
const personaNames:Record<string,[string,string][]>= {orc:[["Meera","Savitri"]],learning:[["Jenny","Rosa"],["Maya","Fatima"]],talent:[["Jenny","Ramabai"]],journeys:[["Maya","Fatima"]],schedules:[],security:[["Maya","Clara"]]};
function personaText(text:string,moduleId:string){return (personaNames[moduleId]||[]).reduce((value,[from,to])=>value.replaceAll(from,to),text)}
type StudyVideo={id:string;title:string;source:string};
const lessonVideos:Record<string,StudyVideo>={
 dff:{id:"1ejKJO-Jpoo",title:"Oracle Fusion Descriptive Flexfields",source:"BISP Oracle HCM"},
 eff:{id:"G2AQQa91I7A",title:"Implementing Extensible Flexfields and Value Sets",source:"Oracle HCM tutorial"},
 kff:{id:"xPp-XjrWZDc",title:"Key Flexfields in Fusion HCM",source:"Oracle Fusion Technical Tutorials"},
 approvals:{id:"NOaR7wMKQSI",title:"HCM approvals, BPM Worklist and ESS",source:"Oracle HCM tutorial"},
 absence:{id:"NlIEN9B7syU",title:"Absence approval workflow and BPM Worklist",source:"Oracle HCM tutorial"}
};
const foundationVideos:Record<string,StudyVideo>={community:{id:"wUSucDHSBMs",title:"Connect with Oracle customers and communities",source:"Oracle"}};
const extensionThemes=[
 ["Regional variation","Extend the solution to a second country or business unit without duplicating the core design."],
 ["Data conversion","Load representative legacy data, control errors and reconcile the converted result."],
 ["Exception handling","Design and prove the missing-data, invalid-value and unavailable-owner paths."],
 ["Reporting and reconciliation","Create an operational control that reconciles source, configuration and reported outcomes."],
 ["Release and support","Move the solution through test to production with regression evidence, rollback and a support handover."]
] as const;
function extraTasks(area:string,level:string,technical=false):TraineeTask[]{const source=(technical?technicalTasks:traineeTasks).filter(t=>t.area===area&&(level==="All"||t.level===level));const resolved=level==="All"?(source[0]?.level||"Level 1"):level;const prefix=(source[0]?.id.split("-")[0]||area.replace(/[^A-Z]/gi,"").slice(0,5).toUpperCase());return extensionThemes.map((theme,i)=>({id:`${prefix}-X${resolved.replace(/\D/g,"")||"1"}${i+1}`,area,level:resolved,name:`${theme[0]} challenge`,brief:`${theme[1]} Apply it to ${area} at ${resolved}.`,requirements:[`Interpret a realistic ${area} client requirement at ${resolved} and record assumptions, actors and success measures.`,theme[1],"Reuse the existing design where appropriate and document every deliberate variation, dependency and control.","Demonstrate the configured or technical outcome with traceable evidence and explain how defects will be handled."],deliverables:["Requirement document and traceability matrix","Detailed solution/design document","Configuration or build evidence","UAT document, results and handover notes"],tests:["Positive end-to-end scenario","Negative or missing-data scenario","Boundary or effective-date scenario","Reconciliation and regression scenario"],assessment:`${resolved} extension: requirement clarity, sound ${area} design, exception depth, UAT quality and support readiness.`}))}
type FoundationUnit={id:string;title:string;outcome:string;duration:string;lessons:{title:string;summary:string;points:string[];example:string}[]};
const foundationUnits:FoundationUnit[]=[
 {id:"erp",title:"ERP and Oracle HCM",duration:"45 min",outcome:"Explain where HCM fits inside an enterprise platform.",lessons:[
  {title:"What is ERP?",summary:"ERP is an integrated platform used to run core enterprise processes through shared data, controls and workflows.",points:["Connects functions such as HR, Finance, Procurement and Supply Chain","Uses common reference data and controlled transactions","Reduces isolated systems and duplicate data","Creates an auditable source of truth"],example:"A new hire entered in HCM can drive payroll, identity access, cost allocation and reporting."},
  {title:"Where Oracle HCM fits",summary:"Oracle Fusion Cloud HCM is Oracle’s cloud suite for managing the workforce and the employee lifecycle.",points:["Core HR is the workforce system of record","Talent, Learning, Compensation, Absence and Payroll extend the lifecycle","Security, workflows, integrations and analytics cut across modules","HCM exchanges data with Finance, identity, recruitment and external providers"],example:"A promotion updates assignment, salary, approvals, payroll inputs and downstream identity attributes."}
 ]},
 {id:"community",title:"Oracle Account and Community",duration:"75 min",outcome:"Create an Oracle learning identity, join Customer Connect and participate like a responsible consultant.",lessons:[
  {title:"Create and protect your Oracle Account",summary:"An Oracle Account is the trainee’s identity for Oracle learning, documentation and community services; it is separate from access to a client HCM instance.",points:["Use your own genuine professional details and an email you can retain","Use a unique password and available multifactor protection","Never share a client login, support identifier or confidential attachment","Understand that an Oracle Account does not automatically grant My Oracle Support or customer-instance access"],example:"Meera creates her personal Oracle Account for learning. When she later joins a client, she still receives a separate named HCM user with only the access required for her role."},
  {title:"Register for Cloud Customer Connect",summary:"Logging in with an Oracle Account is not the same as completing Cloud Customer Connect membership registration.",points:["Open Cloud Customer Connect and sign in","Select Register after authentication","Complete the profile and choose all relevant interests","Select Human Capital Management and the modules you are learning","Return to the HCM category and confirm discussions are visible"],example:"Arun can sign in but cannot participate. He completes the Customer Connect profile registration, selects HCM interests and then follows Global HR and Reporting discussions."},
  {title:"Search before asking",summary:"Consultants develop judgement by combining current Oracle documentation, release material and community experience—not by copying the first answer found online.",points:["Start with the exact error, feature and quarterly release","Search Oracle Help Center and Customer Connect separately","Check dates, accepted answers and Oracle employee responses","Reproduce the behaviour safely in the training instance","Record the source link and what you personally validated"],example:"Instead of posting ‘HDL not working’, Jenny searches the exact message, confirms the relevant business object guide, tests the suggested key correction and records the result."},
  {title:"Ask and contribute professionally",summary:"A useful community post gives enough masked evidence for others to reason about the issue and closes the loop when solved.",points:["Use a precise title and state the business outcome","Include release, module, navigation and reproducible steps","Mask names, emails, IDs, URLs, screenshots and customer data","Explain what you already checked and the observed versus expected result","Acknowledge helpful responses and publish the verified resolution"],example:"‘26C Absence: certification not triggered at 8-day boundary’ is useful. The post includes masked setup, 7/8-day tests and expected behaviour—without exposing employee information."}
 ]},
 {id:"instances",title:"Instances and Environments",duration:"60 min",outcome:"Describe the purpose, data and controls of each Oracle environment.",lessons:[
  {title:"What is an instance?",summary:"An instance is a separate Oracle HCM environment with its own configuration, data, users and integrations.",points:["Production runs live business operations","Test environments support configuration and validation","Each pod has its own URL and refresh history","Changes do not automatically move between instances"],example:"A new absence plan is configured in TEST, validated in UAT and migrated to PROD."},
  {title:"Typical environment landscape",summary:"Organisations separate build, test and live work so changes can be controlled.",points:["DEV/CONFIG: build and unit test","TEST/SIT: integration and end-to-end validation","UAT: business acceptance","PROD: live operations","Optional TRAINING, PRE-PROD or support pods"],example:"Payroll may require a dedicated parallel-test pod while Core HR uses a shared SIT pod."},
  {title:"Gold instance",summary:"A gold instance is the trusted baseline containing approved configuration used to seed or compare other environments.",points:["Represents the agreed design baseline","Should exclude uncontrolled experiments","Supports repeatable deployment or rollout","Needs ownership, versioning and reconciliation"],example:"A global template is built in GOLD before localisation is rolled into country pods."}
 ]},
 {id:"lifecycle",title:"Cloning, Masking and SDLC",duration:"75 min",outcome:"Explain how environments are refreshed and how change travels safely to production.",lessons:[
  {title:"Cloning and refresh",summary:"Cloning copies an environment or its data/configuration state into another environment for a defined purpose.",points:["Commonly production-to-test refresh","Overwrites target data and may overwrite target configuration","Requires integration, user and scheduled-process controls","Needs pre-refresh backup and post-refresh checklist"],example:"UAT is refreshed from PROD before annual compensation testing; in-flight UAT work must be protected first."},
  {title:"Data masking",summary:"Masking replaces or obscures sensitive production data when copied into non-production.",points:["Protects names, bank details, national IDs and contact data","Supports privacy and least-access principles","Must be validated after refresh","Does not replace environment security"],example:"Real bank accounts and personal emails are masked before testers receive access."},
  {title:"SDLC for Oracle HCM",summary:"The Software Development Life Cycle controls how a requirement becomes a safe production change.",points:["Discover and clarify requirement","Design and obtain sign-off","Configure and unit test","SIT, UAT and regression","Deploy, validate, hypercare and close"],example:"A transfer approval change carries one requirement ID through design, configuration evidence, tests and release notes."},
  {title:"Migration between pods",summary:"Configuration movement must be planned by artefact type and dependency—not treated as one universal export.",points:["Use FSM configuration packages where supported","Use HDL/HSDL for setup or business data where appropriate","Recreate or separately migrate unsupported artefacts","Sequence dependencies and reconcile after import"],example:"Value sets move before flexfield segments that depend on them."}
 ]},
 {id:"upgrades",title:"Upgrades and Quarterly Updates",duration:"60 min",outcome:"Plan Oracle’s update cycle and protect critical business processes.",lessons:[
  {title:"Upgrade vs update",summary:"In cloud delivery, Oracle applies scheduled quarterly updates; customers validate impact rather than controlling a traditional major upgrade project.",points:["New features, fixes and technical changes arrive regularly","Some features are automatic; others require opt-in","Configuration and extensions can be affected","Release readiness is an ongoing discipline"],example:"A Redwood page change may alter navigation, field behaviour or an existing extension."},
  {title:"Quarterly update schedule",summary:"Oracle Cloud updates follow four annual release families, commonly labelled A, B, C and D.",points:["Non-production is updated before production","The interval is used for regression and issue resolution","Exact dates depend on the customer cadence and environment","Teams maintain a release calendar and ownership matrix"],example:"TEST receives 26C before PROD, giving the team time to validate hire, transfer, termination, payroll and integrations."},
  {title:"Release readiness and regression",summary:"A strong update process converts release notes into risk-based validation.",points:["Review feature and deprecation notes","Map changes to enabled modules and extensions","Run priority end-to-end regression","Record defects, workarounds and opt-ins","Obtain business go/no-go evidence"],example:"Critical P1 flows run every quarter; lower-risk reports rotate based on the impact assessment."}
 ]},
 {id:"employee",title:"Employee Lifecycle",duration:"105 min",outcome:"Trace the worker journey, identify the supporting Fusion modules, and explain the shared OIC, FDI and OAC layers.",lessons:[
  {title:"The employee lifecycle and its Oracle HCM modules",summary:"Follow one employee from sourcing to exit or rehire. Each stage shows the business event, the Oracle HCM module that supports it and the record or outcome produced.",points:["01 · Source candidates → Oracle Recruiting Cloud (ORC)","02 · Recruit and select → ORC","03 · Hire and create the worker → ORC handoff + Global HR / Core HR","04 · Onboard and transition → Journeys and Checklists","05 · Work, record time and take leave → Core HR + Time and Labor + Absence Management","06 · Pay, enrol in benefits and receive rewards → Payroll + Benefits + Workforce Compensation","07 · Learn and build a career → Learning + Career Development","08 · Set goals, assess performance and promote → Goal Management + Performance Management; Core HR records the promotion","09 · Review talent and plan successors → Talent Review + Succession Planning","10 · Transfer, offboard or rehire → Core HR + Journeys + Payroll","COMMON INTEGRATION LAYER · Oracle Integration (OIC) connects HCM stages to other Oracle Cloud modules and approved external applications","COMMON ANALYTICS LAYER · Fusion Data Intelligence (FDI) provides prebuilt Fusion application analytics; Oracle Analytics Cloud (OAC) supports broader governed analysis, visualisation and shared insights"],example:"Jenny is sourced and recruited in ORC. After she accepts, her hire is handed to Core HR, where Oracle creates her person, work relationship and assignment. Journeys supports onboarding; Absence and Time and Labor support daily work; Benefits manages enrolment; Workforce Compensation plans salary and awards; Payroll pays the result. Learning, Goals, Performance and Talent support Jenny’s growth, while Core HR records a promotion or transfer on her assignment."},
  {title:"The shared integration and analytics layers",summary:"OIC, FDI and OAC are not employee-lifecycle stages. They are platform capabilities that can connect or analyse information across HCM, ERP, SCM, CX and other applications.",points:["OIC = integration middleware between Oracle Cloud, third-party and on-premise applications","An integration has a business trigger, source, mapping, target, error path and monitoring owner","FDI = prebuilt, cloud-native analytics for Oracle Fusion Cloud Applications, including HCM analytics","OAC = broader analytics and visualisation platform for governed datasets and cross-source analysis","Operational transactions remain in the source application; analytics does not replace the HCM transaction","Every interface and dashboard still requires security, data ownership, reconciliation and support"],example:"When Jenny is hired, OIC can send worker data to identity and scheduling systems. HCM data can feed prebuilt workforce insights in FDI, while OAC can combine governed HCM information with other approved enterprise data for broader analysis."},
  {title:"Person, work relationship and assignment",summary:"Oracle separates the human identity from their legal employment relationship and operational assignment.",points:["Person: the individual","Work relationship: connection to a legal employer","Assignment: job, department, manager, location and status","One person may have multiple work relationships or assignments"],example:"Jenny can have one person record, a UK work relationship and two assignments."},
  {title:"Actions and effective dating",summary:"Actions describe why a change occurred; effective dates determine when it applies and preserve history.",points:["Action and action reason classify transactions","Date-effective records maintain history","Correction changes an existing history row","Update creates a new effective-dated change","Sequence matters for same-day changes"],example:"Correct a wrong department entered yesterday; update department when a genuine transfer starts next month."}
 ]},
 {id:"ebscloud",title:"Oracle EBS vs Oracle Cloud",duration:"60 min",outcome:"Compare architecture, ownership, configuration and operating models.",lessons:[
  {title:"Architecture and ownership",summary:"E-Business Suite is traditionally customer-managed or hosted; Fusion Cloud is Oracle-operated SaaS with scheduled updates.",points:["EBS allows deeper database/custom-code control","Cloud emphasises configuration, extension and supported APIs","Infrastructure responsibility shifts toward Oracle","Cloud changes arrive on a regular cadence"],example:"A custom EBS form or direct SQL update usually becomes supported configuration, extension or API integration in Cloud."},
  {title:"Implementation mindset",summary:"Moving to Cloud is not a technical rehosting exercise; it requires process and data redesign.",points:["Adopt standard process where possible","Replace customisations with configuration or extensions","Clean and map legacy data","Redesign security and integrations","Establish continuous release governance"],example:"An EBS custom approval package is re-expressed using BPM rules and supported transaction attributes."},
  {title:"Practical comparison",summary:"Trainees must translate familiar EBS language carefully rather than assume a one-to-one feature mapping.",points:["Organisations vs enterprise structures","Responsibilities vs role-based security","Concurrent programs vs scheduled processes","Interfaces vs HDL, HCM Extracts, REST and OIC","Patches/upgrades vs quarterly updates"],example:"An EBS responsibility does not simply become one Cloud job role; duty roles, data roles and security profiles must be designed."}
 ]},
 {id:"enterprise",title:"Enterprise Structures",duration:"90 min",outcome:"Build the statutory and organisational backbone of an HCM implementation.",lessons:[
  {title:"Enterprise and legal structure",summary:"Enterprise structures represent the organisation, statutory employers and reporting boundaries.",points:["Enterprise","Legal entity","Legal employer","Legislative data group","Payroll statutory unit","Business unit"],example:"A global group has UK and India legal employers, each aligned to the appropriate legislative and payroll context."},
  {title:"Business units and reference data",summary:"Business units support management, transaction processing and reference-data sharing without replacing legal employers.",points:["Business units reflect operating responsibility","Reference data sets control shared or local values","Set assignments influence what users can select","Legal and operational structures solve different problems"],example:"One legal employer may contain several business units sharing common jobs but using local departments."},
  {title:"Design and sequencing",summary:"Enterprise structure design begins with statutory facts and business operating requirements.",points:["Confirm countries and employing entities","Separate legal, payroll and managerial needs","Define naming and coding standards","Map reference-data sharing","Sequence foundation setup and validate consumers"],example:"Do not create a new legal employer merely because a new internal division is formed."}
 ]},
 {id:"workforce",title:"Workforce Structures and Basic Setup",duration:"4 hrs",outcome:"Design, configure and test the structures used to place, classify and manage workers.",lessons:[
  {title:"The workforce structure map",summary:"Workforce structures answer five simple questions: what work, which seat, at what level, in which team and at what place.",points:["Job = type of work","Position = specific seat","Grade = level or value","Department = organisational team","Location = work place"],example:"In a supermarket, Cashier is the job; Cashier–Store 114–Evening is the position; Grade 2 is the level; Store Operations is the department; Milton Keynes Store is the location."},
  {title:"Jobs",summary:"A job describes a reusable type of work independent of one employee or one vacancy.",points:["Job name and code","Job family and function","Set-enabled sharing","Effective dates","Job profiles and downstream use"],example:"‘HR Business Partner’ is one job reused by HRBPs in London, Chennai and Dubai."},
  {title:"Positions",summary:"A position is a specific authorised seat in the organisation and can carry defaults and headcount control.",points:["Position code and name","Job, department, location and business unit","Hiring status and FTE","Incumbent and headcount rules","Position hierarchy where used"],example:"‘UK HRBP–Retail–London–01’ is one seat. When Asha leaves, the position remains and another person can fill it."},
  {title:"Job model vs position model",summary:"The operating model determines whether assignments are driven mainly by jobs or by controlled positions.",points:["Job model offers flexibility","Position model offers stronger seat control","Hybrid approaches are common","Budget and vacancy control influence the choice","Do not create positions merely to copy employee names"],example:"A small consultancy hires consultants directly to jobs; a hospital controls every nurse and doctor vacancy through positions."},
  {title:"Grades, ladders and rates",summary:"Grades classify relative level; ladders order grades; rates can hold monetary or non-monetary values.",points:["Grade codes and names","Grade ladder sequence","Grade rates","Salary basis relationship","Eligibility and progression"],example:"G5, G6 and G7 sit in a Professional ladder; a promotion moves Jenny from G6 to G7."},
  {title:"Departments",summary:"Departments represent organisational teams or cost-owning units—not buildings or job titles.",points:["Department naming and coding","Owning business unit","Set assignment","Effective dates","Manager, security, approval and reporting use"],example:"Finance Operations is a department containing accountants in both London and Manchester locations."},
  {title:"Locations",summary:"Locations represent physical or logical work places and hold address and country information.",points:["Location code and address","Country and geography validation","Active and inactive dates","Remote or virtual locations","Payroll, tax and reporting impact"],example:"London HQ is a location used by HR, Finance and Technology departments; it is not itself a department."},
  {title:"Actions, reasons and statuses",summary:"Actions explain why a workforce transaction happened; reasons add detail; statuses control assignment behaviour.",points:["Hire, transfer, promotion and termination actions","Action reasons","Assignment status types","User and payroll statuses","Reporting consistency"],example:"Action: Transfer; Reason: Office Relocation. This is clearer than inventing a new action called ‘London move’."},
  {title:"Reference data sets and sharing",summary:"Reference data sets decide whether workforce values are shared globally or restricted to a business context.",points:["Common set","Business-unit-specific sets","Set-enabled objects","Reference data set assignments","Duplicate-value and maintenance risk"],example:"Global jobs use the Common Set, while a UK-only regulated job belongs to the UK reference set."},
  {title:"Build sequence and end-to-end testing",summary:"Structures must be configured in dependency order and proven through an employee transaction.",points:["Confirm enterprise structures and sets","Build grades/jobs/departments/locations","Build positions after dependencies","Test hire, transfer and promotion","Validate security, approvals, HDL and reports"],example:"Create the job, grade, department and location first; then create the position and hire Maya into it. Finally transfer her and confirm every default and report."}
 ]},
 {id:"trees",title:"Trees and Department Trees",duration:"5 hrs",outcome:"Explain, build, version, audit, flatten, consume and maintain Oracle HCM hierarchies safely.",lessons:[
  {title:"Why organisations need trees",summary:"A flat list tells us what values exist; a tree tells us how they roll up to one another.",points:["Parent-child hierarchy","Roll-up and drill-down","Multiple business uses","Not the same as the department master list","Consumer requirements drive design"],example:"A school has English, Maths and Science departments. A tree groups all three under Academic Departments and then under the whole School."},
  {title:"Tree vocabulary",summary:"Tree structure, tree code, tree version and node are separate building blocks and should not be used interchangeably.",points:["Tree structure = rules or template","Tree code = named logical hierarchy","Tree version = dated content","Node = a value placed in the hierarchy","Root, parent, child, sibling and leaf"],example:"Filing cabinet type = structure; cabinet label = tree code; this year’s filing arrangement = version; each folder = node."},
  {title:"Tree structures",summary:"The structure controls what kind of values may become nodes and how the hierarchy behaves.",points:["Data source for nodes","Allowed node types","Depth and relationship expectations","Seeded vs configured structure","Consumer compatibility"],example:"A family-tree template permits people as nodes; a department-tree structure permits department values—not locations or employees."},
  {title:"Tree codes and business purpose",summary:"A tree code identifies one logical hierarchy across time and must have a clear owner and purpose.",points:["Stable naming","One stated business purpose","Ownership and change approval","Difference between alternative hierarchies","Avoid duplicate trees with unclear use"],example:"CHC_GLOBAL_DEPT is the logical department hierarchy; its 2026 and 2027 layouts are versions of the same tree code."},
  {title:"Tree versions and effective dates",summary:"Versions allow the hierarchy to change over time without destroying the arrangement used historically.",points:["Draft, active and inactive states","Start and end dates","Non-overlapping active versions","Future-dated restructuring","Historical reporting"],example:"Retail moves under Consumer Business on 1 January. Keep the 2026 version and create a 2027 version effective from 1 January."},
  {title:"Nodes and hierarchy design",summary:"Nodes must form a complete, unambiguous hierarchy with sensible roll-up levels.",points:["Root and intermediate nodes","Leaf departments","No orphan nodes","Duplicate-node rules","Balanced vs unbalanced depth","Node order"],example:"CHC Group → UK → Operations → Stores → Milton Keynes Store Operations. Finance should not appear under both UK and India unless the design explicitly allows it."},
  {title:"Building a Department Tree",summary:"A Department Tree places existing department values into reporting and security relationships.",points:["Create departments first","Choose the correct structure and tree code","Add and organise nodes","Create version dates","Audit then activate","Confirm every required department is included"],example:"Departments Sales North and Sales South exist separately; the tree rolls them into UK Sales for the Sales Director."},
  {title:"Audit, validation and flattening",summary:"Audit checks whether the tree obeys its rules; flattening prepares hierarchy relationships for efficient consumption.",points:["Run audit before activation","Resolve missing or invalid nodes","Understand audit errors vs warnings","Flatten after hierarchy changes where required","Validate that consumers see the new version"],example:"A new department exists but is not placed in the active tree. Audit or reconciliation identifies it before HR security relies on the hierarchy."},
  {title:"How Trees are consumed",summary:"Trees become valuable only through consumers such as security, reporting, workforce planning and compensation.",points:["Organisation security profiles","AOR and population access considerations","OTBI hierarchy prompts and roll-ups","Workforce compensation and modelling","Approval or extract logic where configured"],example:"An HRBP granted access to UK Operations can see every worker in departments beneath that node—but not workers in UK Finance."},
  {title:"Maintenance and troubleshooting",summary:"Tree changes require impact assessment because moving one node can silently change data access and reports.",points:["New department placement","Department end dating","Node moves and reorganisations","Future-version governance","Audit/flattening failures","Regression of every registered consumer"],example:"Moving Payroll from Finance to HR may change HRBP access, headcount reports and compensation worksheets. Test all three before activation."}
 ]}
];
const foundationAssessments=[
 {id:"FND-01",level:"Level 1",name:"Explain an ERP Hire",brief:"Using one new-hire example, show how HCM, payroll, identity and finance share data. Produce a one-page process map and glossary."},
 {id:"FND-02",level:"Level 1",name:"Map the Environment Landscape",brief:"Define DEV, SIT, UAT, TRAIN and PROD purposes, permitted users/data and exit criteria for a fictional implementation."},
 {id:"FND-03",level:"Level 2",name:"Plan a Production Clone",brief:"Create pre-clone, masking and post-clone checklists including integrations, users, scheduled jobs and reconciliation."},
 {id:"FND-04",level:"Level 2",name:"Quarterly Update Calendar",brief:"Build an A/B/C/D annual plan covering release-note review, test update, regression, opt-ins, defects and production go/no-go."},
 {id:"FND-05",level:"Level 3",name:"Employee Lifecycle Trace",brief:"Trace hire, manager change, absence, promotion, international transfer and termination through person, work relationship and assignment."},
 {id:"FND-06",level:"Level 3",name:"EBS-to-Cloud Translation",brief:"Map ten EBS concepts or customisations to supported Cloud configuration, security, migration and integration approaches."},
 {id:"FND-07",level:"Level 4",name:"Two-Country Enterprise Design",brief:"Design enterprise, UK/India legal employers, LDGs, PSUs, business units and reference-data sets with stated assumptions."},
 {id:"FND-08",level:"Level 4",name:"Workforce Structure Build",brief:"Create jobs, grades, positions, departments and locations for a retail organisation, including codes, effective dates and dependencies."},
 {id:"FND-09",level:"Level 5",name:"Department Tree Redesign",brief:"Design current and future-dated tree versions, node movements, audit checks, security/reporting impact and regression tests."},
 {id:"FND-10",level:"Level 6",name:"Foundation Design Authority Review",brief:"Review a flawed global HCM foundation design, identify statutory, structural, environment and governance risks, then present a remediation roadmap."}
];
const newBasicTaskSpecs:{area:string;prefix:string;items:{name:string;brief:string;features:string;test:string}[]}[]=[
 {area:"OTBI",prefix:"OTBI",items:[
  {name:"Active Worker List",brief:"Build a secured list of active employees with assignment and manager details.",features:"Workforce subject area; person versus assignment grain; active filter; effective date; table view",test:"one worker, multiple assignments, inactive worker and two users with different access"},
  {name:"Headcount Dashboard",brief:"Create headcount analysis by legal employer, business unit and department.",features:"facts and dimensions; dashboard prompts; pivot totals; chart; drill detail",test:"headcount totals, prompt combinations, multiple assignments and empty department"},
  {name:"Joiner and Leaver Analysis",brief:"Report hires and terminations for a prompted date range.",features:"event dates; action/action reason; prompts; calculated month; dashboard views",test:"boundary dates, rehire, cancelled termination and security"},
  {name:"Absence Monitoring Dashboard",brief:"Build manager and HR views of absence records and balances.",features:"absence subject areas; duration; reason; plan balance; manager hierarchy; agent",test:"open-ended absence, partial day, manager access and balance reconciliation"},
  {name:"Executive Workforce Pack",brief:"Deliver a governed multi-page dashboard with headcount, movement and data-quality measures.",features:"multiple subject areas; KPIs; prompts; agents; catalog governance; reconciliation",test:"cross-report totals, user security, performance, scheduled delivery and regression"}
 ]},
 {area:"Alert Composer",prefix:"ALT",items:[
  {name:"Contract Expiry Reminder",brief:"Notify manager 30 days before a fixed-term contract ends.",features:"worker resource; date condition; manager recipient; tokens; link",test:"29/30/31-day boundaries, missing manager and extended contract"},
  {name:"Probation End Alert",brief:"Notify worker, manager and HRBP before probation ends.",features:"scheduled alert; multiple recipients; AOR resolution; personalised content; stop condition",test:"recipient resolution, passed probation, missing HRBP and duplicate suppression"},
  {name:"Missing Bank Details Alert",brief:"Remind eligible new hires to complete bank details without exposing sensitive data.",features:"population filters; hire date; completion condition; reminders; secure wording",test:"complete/incomplete details, non-payroll worker, reminder cycle and stop condition"},
  {name:"Long-Open Position Alert",brief:"Escalate positions left open beyond policy thresholds.",features:"position resource; elapsed days; staged recipients; frequency; escalation",test:"threshold boundaries, filled/frozen positions, duplicate prevention and escalation"},
  {name:"Global Data Quality Alerts",brief:"Create a monitored alert suite for missing manager, department and work email.",features:"three resources/conditions; recipient strategy; scheduling; suppression; support ownership",test:"all defect combinations, correction stop, volumes, delivery failure and quarterly regression"}
 ]},
 {area:"HDL/HSDL",prefix:"HDL",items:[
  {name:"Load Departments",brief:"Create ten departments through HDL using stable source keys.",features:"Organization business object; source owner/id; effective dates; reference set",test:"10 creates, invalid set, retry with same key and reconciliation"},
  {name:"Maintain Locations",brief:"Create and correct locations through a restricted HSDL template.",features:"template fields; role access; user/source keys; addresses; correction",test:"valid create, missing required field, correction and unauthorised user"},
  {name:"Worker Hire Load",brief:"Load workers, work relationships and assignments from a legacy file.",features:"Worker components; parent-child keys; legal employer; job/department/location; errors",test:"valid hires, missing parent, duplicate key and UI reconciliation"},
  {name:"Date-Effective Assignment Changes",brief:"Load historical, current and future department changes without damaging history.",features:"effective dates; UPDATE/CORRECTION; retain/replace future; sequence",test:"correction, genuine update, future row, multiple same-day changes and history"},
  {name:"Conversion and Business Loader Service",brief:"Design migration loads plus governed HSDL templates for ongoing HR operations.",features:"object sequencing; source keys; template security; error handling; reconciliation; support",test:"volume, dependencies, restart, duplicate prevention, security and control totals"}
 ]},
 {area:"Fast Formula",prefix:"FF",items:[
  {name:"FTE Entitlement Formula",brief:"Return annual entitlement as 25 days multiplied by FTE.",features:"formula type; input; default; IF validation; return value",test:"FTE 1, 0.6, 0, null and above 1"},
  {name:"Service Band Formula",brief:"Return 22, 25 or 28 days using completed service bands.",features:"service database item/input; boundary logic; defaults; returns",test:"below/equal/above 3 and 8 years plus null service"},
  {name:"Absence Entry Validation",brief:"Reject a request over ten days unless an approved exception indicator exists.",features:"validation formula type; duration input; exception value; user message",test:"9/10/11 days, exception yes/no and partial day"},
  {name:"Complex Accrual Proration",brief:"Calculate entitlement using service band, FTE and mid-year hire date.",features:"contexts; database items; dates; band logic; rounding; return",test:"three service bands, FTE variants, join dates and rounding boundaries"},
  {name:"Formula Review and Remediation",brief:"Diagnose and rewrite an undocumented formula producing incorrect balances.",features:"formula contract; contexts; database items; null handling; comments; versioning",test:"reproduce defect, boundary suite, performance, regression and handover"}
 ]},
 {area:"Work Schedules",prefix:"SCH",items:[
  {name:"Standard Office Schedule",brief:"Create a 9–5 Monday-to-Friday schedule with lunch and weekends.",features:"shift; pattern; schedule; duration; assignment",test:"weekly hours, working/non-working days and effective date"},
  {name:"Part-Time Working Pattern",brief:"Configure a Monday-Wednesday-Friday worker and validate leave duration.",features:"part-time shifts; non-working days; schedule assignment; absence calculation",test:"one week leave, Tuesday request, partial day and public holiday"},
  {name:"Rotating Nurse Roster",brief:"Model two day shifts, two night shifts and four rest days.",features:"overnight shift; repeating pattern; hours; schedule; roster validation",test:"cycle repetition, overnight duration, rest day and absence across cycle"},
  {name:"Schedule Change and Holiday Calendar",brief:"Move workers to a four-day week and apply country public holidays prospectively.",features:"future dating; calendar events; hierarchy/override; absence impact",test:"before/after change, holiday, override and retro entry"},
  {name:"Multi-Population Schedule Framework",brief:"Design office, retail and 24/7 operations schedules with controlled assignment and support.",features:"schedule catalogue; hierarchy; HDL assignment; governance; absence/time regression",test:"all populations, transfer, missing schedule, bulk load and reconciliation"}
 ]},
 {area:"Operations",prefix:"OPS",items:[
  {name:"Run and Reconcile a Process",brief:"Submit an HCM scheduled process and explain parameters, status and output.",features:"process selection; parameters; log; output; reconciliation",test:"success, no-data result and invalid parameter"},
  {name:"Audit a Worker Change",brief:"Prove who changed a worker department and what the old value was.",features:"audit policy awareness; audit report; user/date/object filters; evidence",test:"update, correction, wrong date range and restricted access"},
  {name:"Resolve a Failed Transaction",brief:"Diagnose a transfer stuck because the approver cannot resolve.",features:"Transaction Console; status; assignee; error; recovery decision",test:"missing approver, corrected setup, recover/withdraw and audit"},
  {name:"Population Balance Incident",brief:"Investigate incorrect absence balances after year-end processing.",features:"process history; configuration comparison; logs; sample workers; root cause",test:"working/failing workers, rerun risk, correction and reconciliation"},
  {name:"Quarterly Operational Runbook",brief:"Create process monitoring, audit, incident and Oracle SR procedures for the support team.",features:"process calendar; controls; evidence templates; escalation; SR checklist; regression",test:"failed job, stuck transaction, access issue, rollback and support simulation"}
 ]},
 {area:"Redwood/VBS",prefix:"RW",items:[
  {name:"Hide a Non-Required Field",brief:"Hide a Redwood field for employees while retaining it for HR.",features:"page identification; business rule; role condition; publish",test:"employee, manager and HR personas plus unaffected channel"},
  {name:"Required Transfer Reason",brief:"Make Transfer Reason required for UK HR on the Redwood transfer page.",features:"action/country condition; required property; error behaviour; rule naming",test:"UK transfer, other action, other country and HDL"},
  {name:"Country-Specific Page Rules",brief:"Show UK and India compliance fields to the correct HR populations.",features:"multiple conditions; visible/read-only; rule priority; persona",test:"country/role combinations, conflicting rule and accessibility"},
  {name:"Redwood Migration Regression",brief:"Move a business process from responsive to Redwood and preserve required behaviour.",features:"as-is inventory; gap analysis; supported rules; extension migration; regression",test:"personas, actions, countries, approvals and integrations"},
  {name:"Extension Governance Pack",brief:"Design and govern multiple Redwood rules across hire, transfer and termination.",features:"extension register; ownership; migration; conflict control; quarterly testing",test:"rule combinations, rollback, pod migration, quarterly update and handover"}
 ]},
 {area:"BIP/Extracts",prefix:"BIP",items:[
  {name:"Employment Confirmation Letter",brief:"Create a parameterised, formatted employment letter.",features:"data model; worker parameter; RTF template; Custom folder",test:"two workers, missing data, security and PDF output"},
  {name:"Scheduled Headcount PDF",brief:"Deliver a monthly formatted headcount report to HR leadership.",features:"data model; parameters; layout; schedule; email delivery",test:"month boundary, totals, recipient, failed delivery and rerun"},
  {name:"Benefits Vendor Extract",brief:"Send eligible worker and assignment data in CSV each week.",features:"extract data groups; records/attributes; eligibility; CSV delivery",test:"eligible/ineligible, multiple assignments, counts and sample fields"},
  {name:"Hierarchical Worker Extract",brief:"Produce worker root records with assignment and contact child rows.",features:"root/child groups; links; parameters; formatting; delivery",test:"multiple children, missing contact, termination and hierarchy validation"},
  {name:"Production Outbound Interface",brief:"Design a monitored, encrypted extract with control totals and restart procedures.",features:"full extract design; BIP template; schedule; delivery; encryption; reconciliation; support",test:"volume, totals, delivery failure, retry, duplicates and quarterly regression"}
 ]},
 {area:"Security/AOR",prefix:"SEC",items:[
  {name:"Explain a User’s Access",brief:"Trace one HR user from data role through job role, duties and security profile.",features:"role inheritance; function vs data; profile scope; evidence",test:"menu access, in-scope worker and out-of-scope worker"},
  {name:"UK HR Data Role",brief:"Configure and test access to UK workers only using provided security design.",features:"job role; data role; person profile; organisation scope",test:"UK positive, India negative, multiple assignments and terminated worker"},
  {name:"Department HRBP AOR",brief:"Create HRBP responsibility for selected departments and use it in an approval.",features:"responsibility type; scope; dates; representative resolution",test:"in/out departments, date boundary, missing AOR and approval"},
  {name:"Automatic Role Provisioning",brief:"Provision HR Specialist access from assignment criteria and remove it when eligibility ends.",features:"role mapping; conditions; autoprovision; deprovision; refresh",test:"eligible hire, transfer in/out, termination and multiple assignments"},
  {name:"Access Incident Review",brief:"Diagnose excessive and missing access across roles, profiles and AORs and prepare remediation.",features:"role comparison; inheritance; data scope; AOR; process refresh; audit",test:"five incident scenarios, least privilege, remediation validation and handover"}
 ]}
];
const newBasicTasks:TraineeTask[]=newBasicTaskSpecs.flatMap(s=>s.items.map((x,i)=>({id:`${s.prefix}-${String(i+1).padStart(2,"0")}`,area:s.area,level:`Level ${i+1}`,name:x.name,brief:x.brief,requirements:[`Interpret and confirm the client requirement: ${x.brief}`,`Configure and document: ${x.features}.`,"Record assumptions, dependencies, security and operational ownership.","Complete the transaction or process end-to-end and reconcile the result."],deliverables:["Business requirement and assumptions","Detailed functional/configuration design","Configuration evidence and traceability","SIT test script, results and handover note"],tests:x.test.split(", ").map(t=>t.charAt(0).toUpperCase()+t.slice(1)),assessment:`Level ${i+1} functional accuracy, design judgement, evidence, troubleshooting and client-ready documentation.`})));
type TechSpec={area:string;prefix:string;items:[string,string,string,string][]};
type TechLearningArea={area:string;label:string;plain:string;example:string;lessons:{title:string;focus:string}[];watch:string};
const technicalLearningAreas:TechLearningArea[]=[
 {area:"OIC",label:"Oracle Integration Cloud (OIC)",plain:"OIC is the integration layer that receives, transforms, routes and monitors data between Oracle HCM and other systems. A developer at this level should build dependable orchestrations and support them—not design an enterprise integration estate.",example:"A new hire is created in HCM. OIC reads the worker, converts HCM fields into the IT service desk format, creates the account request and records the returned ticket number.",lessons:[{title:"Connections and adapters",focus:"Endpoints, credentials, agents, HCM adapters and connection testing."},{title:"App-driven orchestration",focus:"Triggers, invokes, mappings, lookups and business identifiers."},{title:"Scheduled integration",focus:"Parameters, watermarks, pagination, full versus delta processing."},{title:"Fault handling",focus:"Scopes, retries, callbacks, re-submission and notifications."},{title:"Promotion and support",focus:"Packages, environment values, activation, monitoring and runbooks."}],watch:"A successful green instance is not enough: prove duplicates, partial failures, replay and reconciliation."},
 {area:"Integration Patterns",label:"Integration Patterns & Events",plain:"The pattern decides how and when data moves. Choose bulk, real-time, scheduled or event-driven processing according to volume, urgency, ownership and recovery needs.",example:"Payroll needs all worker changes nightly, so use a delta extract. IT needs a hire quickly, so consume a hire event and call an API. A conversion uses HDL because it is bulk inbound data.",lessons:[{title:"Inbound versus outbound",focus:"System of record, direction, ownership and data contract."},{title:"Bulk versus real time",focus:"HDL, Extracts, REST/SOAP and latency-volume trade-offs."},{title:"Events and Atom feeds",focus:"Watermarks, event payloads, replay and ordering."},{title:"Full and delta design",focus:"Change windows, late changes, deletes and reconciliation."},{title:"Reliability patterns",focus:"Idempotency, correlation, retry, dead-letter and restart."}],watch:"Do not select REST merely because it feels modern; a nightly 100,000-row feed may need a bulk pattern."},
 {area:"SQL and HCM Data Model",label:"SQL & HCM Data Model",plain:"SQL turns reporting requirements into accurate data sets. The essential skill is understanding HCM keys, effective dates and row grain before writing joins.",example:"A headcount report must return one current primary assignment per worker. Joining person and assignment tables without date and primary filters produces duplicates and wrong totals.",lessons:[{title:"Relational SQL basics",focus:"SELECT, WHERE, JOIN, GROUP BY, CASE and null handling."},{title:"HCM keys and grain",focus:"Person, assignment, work relationship and surrogate identifiers."},{title:"Effective dating",focus:"Effective start/end dates, current rows and as-of-date parameters."},{title:"Common HCM joins",focus:"Names, organisations, jobs, locations, supervisors and legislative data."},{title:"Performance and reconciliation",focus:"Selective filters, avoiding row multiplication and proving totals."}],watch:"Never fix duplicate rows with DISTINCT until you understand which join or grain created them."},
 {area:"Files and Security",label:"Files, SFTP & Encryption",plain:"File integration work covers the complete journey from naming and creation through secure transfer, acknowledgement, archive and recovery.",example:"Every Friday HCM sends a benefits file to a vendor by SFTP. The file is PGP-encrypted, includes a control total, receives an acknowledgement and is archived for audit.",lessons:[{title:"File contracts",focus:"CSV/XML/fixed-width formats, headers, trailers, encoding and names."},{title:"SFTP operations",focus:"Folders, keys, permissions, host keys and connectivity tests."},{title:"Encryption",focus:"PGP public/private keys, signing, rotation and expiry."},{title:"Controls and acknowledgements",focus:"Checksums, counts, manifests, ACK/NACK and duplicate prevention."},{title:"Retention and recovery",focus:"Archive, re-send, audit evidence and support ownership."}],watch:"SFTP protects transport; sensitive files may still require file-level encryption at rest and after delivery."},
 {area:"Migration and Release",label:"Configuration Migration & Release",plain:"Technical changes must move consistently from build to test and production with dependencies, approvals, evidence and rollback understood.",example:"A BIP report, its data model, an OIC integration and environment-specific connections are promoted together. The release plan lists order, validation and rollback for each artefact.",lessons:[{title:"Artefact inventory",focus:"What moves by FSM, archive, package or manual configuration."},{title:"Dependencies",focus:"Flexfields, lookups, roles, formulas, reports and connections."},{title:"Environment parameters",focus:"URLs, folders, credentials, schedules and feature settings."},{title:"Release execution",focus:"Versioning, approvals, sequencing, smoke tests and evidence."},{title:"Rollback and regression",focus:"Backout choices, data impact, quarterly updates and support handover."}],watch:"Configuration migration is not a blind copy: environment-specific values and data changes need separate control."},
 {area:"Technical Redwood/VBS",label:"Technical Redwood & VB Studio",plain:"This area covers safe page extensions for Redwood experiences: business rules, fields, validations and controlled deployment. It is targeted extension work, not full custom-application architecture.",example:"HR wants an Assignment DFF shown only for UK transfers and required for one action. A VB Studio business rule controls visibility and validation without altering Oracle-delivered code.",lessons:[{title:"Redwood extension model",focus:"Delivered pages, extension boundaries and supported changes."},{title:"Business rules",focus:"Conditions, required/read-only/hidden behaviour and precedence."},{title:"Page extensions",focus:"Fields, constants, layouts and sandbox/workspace concepts."},{title:"Services and validation",focus:"REST-backed data, errors, security and performance awareness."},{title:"Lifecycle",focus:"Publish, migrate, test, rollback and quarterly-update checks."}],watch:"A field hidden in the page is not secured; data security and service access remain separate controls."},
 {area:"Payroll Interfaces",label:"Payroll & Third-Party Interfaces",plain:"Developers should understand how HR changes feed payroll, benefits, time, banking and other vendors, including cut-offs, effective dates and reconciliation.",example:"A payroll vendor receives hires, assignment changes, salary, bank and termination data. Files after the cut-off are held for the next run and every accepted/rejected record is reconciled.",lessons:[{title:"Interface scope",focus:"Worker events, elements, balances, bank and costing data."},{title:"Payroll timing",focus:"Cut-offs, retro changes, effective dates and run calendars."},{title:"Vendor mapping",focus:"Codes, transformations, defaults and reference-data ownership."},{title:"Inbound results",focus:"ACK/NACK, payslip or result feeds, rejects and corrections."},{title:"Controls",focus:"Counts, amounts, privacy, audit and payroll sign-off."}],watch:"Do not treat payroll as just another file: one missed effective date can affect pay and requires strict business reconciliation."},
 {area:"Monitoring and Support",label:"Integration Monitoring & Production Support",plain:"Production support joins monitoring, diagnosis, recovery and communication across HDL, Extracts, APIs, OIC, schedules and file delivery.",example:"A benefits feed finishes successfully but the vendor receives no file. The support analyst traces the run ID, delivery log and SFTP path, re-sends safely and records root cause.",lessons:[{title:"Observability",focus:"Run IDs, business identifiers, logs, metrics and dashboards."},{title:"Incident triage",focus:"Application, data, connection, security and scheduling failures."},{title:"Safe recovery",focus:"Retry, restart, replay, re-send and duplicate controls."},{title:"Reconciliation",focus:"Source-target counts, control totals and business confirmation."},{title:"Service operations",focus:"Severity, SLA, communications, RCA, problem records and runbooks."}],watch:"Never re-run blindly; first establish what completed and whether a retry would duplicate business data."}
];
