const traineeTasks:TraineeTask[]=[...newBasicTasks,...orcTasks,...learningTasks.map(t=>({...t,area:"Oracle Learn"})),...talentTasks,
 {id:"JRN-01",area:"Checklists",level:"Level 1",name:"New Hire First-Week Checklist",brief:"Create a simple onboarding journey for one UK office employee.",requirements:["Create an active UK New Hire template in the appropriate category.","Add worker tasks to read the handbook and confirm personal details.","Add manager tasks to welcome the employee and agree first-week meetings.","Set clear due dates from the hire/start-date context and allocate to a test worker."],deliverables:["Short requirement document","Template/task/performer design","Configuration screenshots","Basic execution test"],tests:["Allocate to eligible new hire","Worker and manager see correct tasks","Complete every task","Journey status reaches completion"],assessment:"Template versus allocation, simple task types, performers, dates and complete evidence."},
 {id:"JRN-02",area:"Checklists",level:"Level 1",name:"Employee Offboarding Checklist",brief:"Coordinate a basic resignation across employee, manager, HR and IT.",requirements:["Create an Offboarding journey triggered or allocated for voluntary termination.","Add return-assets, knowledge-handover, final-details and access-removal tasks.","Assign each task to a clear performer.","Schedule tasks before or on the termination date."],deliverables:["Requirement and task inventory","Performer/RACI matrix","Configuration design","Positive test script"],tests:["Correct worker allocation","Due-date offsets","Every persona sees assigned work","Early and late task completion"],assessment:"Client-process translation, ownership, sensible sequencing and closure."},
 {id:"JRN-03",area:"Checklists",level:"Level 2",name:"Remote-Worker Onboarding Variation",brief:"Use eligibility so remote hires receive additional equipment and home-working tasks.",requirements:["Keep one UK onboarding template for office and remote workers.","Add task-level eligibility for Home Office Risk Assessment and Courier Equipment.","Use questionnaire, document and manual task types appropriately.","Test office and remote populations without manually deleting tasks."],deliverables:["Population requirement and eligibility matrix","Task-type selection rationale","Template design","Comparative test pack"],tests:["Remote hire receives extra tasks","Office hire does not receive them","Questionnaire completion","Missing/changed remote indicator"],assessment:"Task-level eligibility, task-type choice, shared-template design and population testing."},
 {id:"JRN-04",area:"Checklists",level:"Level 2",name:"Promotion Readiness Journey",brief:"Guide an employee and manager through a promotion after the transaction is approved.",requirements:["Create a Promotion journey with employee, manager and HR tasks.","Include role expectations, learning plan, compensation letter and 30-day review.","Use dependencies so the letter precedes acknowledgement and the review follows acknowledgement.","Set dates relative to the promotion effective date."],deliverables:["Requirement/process map","Task/dependency/date design","Notification copy","SIT tests"],tests:["Correct allocation date","Dependency blocks early task","Effective-date offsets","Worker acknowledgement and final status"],assessment:"Event context, dependencies, performer ownership and milestone timing."},
 {id:"JRN-05",area:"Checklists",level:"Level 3",name:"Country-Specific Global Onboarding",brief:"Design one controlled onboarding framework for UK and India new hires.",requirements:["Define shared global tasks and country-specific eligible tasks.","UK tasks include right-to-work evidence; India tasks include UAN and local policy acknowledgement.","Use employee, manager, HR and IT performers.","Configure assignment, reminder and overdue notifications without duplicating unnecessary templates."],deliverables:["Global/local requirement matrix","Eligibility and performer design","Notification calendar","End-to-end SIT pack"],tests:["UK and India new hires","Country task separation","Missing HR/IT performer","Reminder and overdue behaviour"],assessment:"Global-template judgement, localisation, notifications and exception handling."},
 {id:"JRN-06",area:"Checklists",level:"Level 3",name:"Reusable Equipment Task Group",brief:"Create common equipment tasks that can be reused in onboarding, transfer and return-to-office journeys.",requirements:["Design a task group containing request, dispatch, receipt and confirmation tasks.","Use dependencies and completion criteria within the group.","Apply appropriate performer and eligibility rules.","Add the group to three journey templates and document change impact."],deliverables:["Reuse requirement and usage register","Task-group design","Dependency/eligibility specification","Regression tests"],tests:["Group in all three templates","Dependent execution order","Eligibility variation","Template behaviour after a controlled group change"],assessment:"Reusable design, dependency logic, usage impact and regression awareness."},
 {id:"JRN-07",area:"Checklists",level:"Level 4",name:"Long-Term Sickness Return-to-Work Journey",brief:"Coordinate manager, HR, Occupational Health and employee activities after a long absence.",requirements:["Allocate the journey when HR confirms a return-to-work process is required.","Include confidential-review boundaries, workplace-adjustment tasks and phased-return planning.","Use eligibility, dependencies and reminders across performers.","Define who can view and manage the allocated journey and its evidence."],deliverables:["Sensitive-process BRD and personas","Template/security/dependency design","Notification and evidence design","SIT/UAT pack"],tests:["Correct worker and performer access","Dependency and overdue escalation","Missing Occupational Health performer","Reassignment and journey closure"],assessment:"Sensitive process design, access, multi-performer coordination and exception management."},
 {id:"JRN-08",area:"Checklists",level:"Level 4",name:"Mass Compliance Acknowledgement",brief:"Allocate a mandatory policy journey to 3,000 workers and monitor completion.",requirements:["Create document, video or questionnaire tasks that capture appropriate completion evidence.","Define mass-allocation population and prevent duplicates.","Configure reminders and management escalation by due date.","Design status reporting, reconciliation and support for allocation failures."],deliverables:["Requirement and population rules","Mass-allocation and communication design","Reporting/reconciliation specification","Volume and exception test pack"],tests:["Sample eligible/ineligible workers","Duplicate allocation prevention","Reminder/escalation milestones","Failed allocation and completion reporting"],assessment:"Volume planning, evidence, communications, reconciliation and supportability."},
 {id:"JRN-09",area:"Checklists",level:"Level 5",name:"Global Onboarding Operating Model",brief:"Build a maintainable onboarding journey service for UK, India and UAE business units.",requirements:["Define shared templates, local variants, task library/task groups and category ownership.","Cover automatic allocation, eligibility, performers, dependencies, notifications and documents.","Design category security, HR access and allocated-journey maintenance.","Prepare rollout, migration of active new hires, regression and support handover."],deliverables:["Functional BRD and design principles","Detailed journey catalogue and configuration design","Security/reporting/integration specifications","Deployment, regression and operating guide"],tests:["Three-country populations","Rehire and internal-transfer edge cases","Missing performer and duplicate allocation","Existing allocations after template change"],assessment:"Senior-consultant functional design, governance, rollout control and operational readiness—not architecture."},
 {id:"JRN-10",area:"Checklists",level:"Level 5",name:"Event-Driven Employee Lifecycle Journeys",brief:"Implement joined-up journeys for hire, transfer, promotion, parental leave return and termination.",requirements:["Map each event to the correct journey, allocation method and person/assignment context.","Define reusable tasks while preventing irrelevant or duplicate allocations.","Cover date changes, rescinded transactions, reassignments and incomplete journeys.","Design REST/HDL needs, dashboards, quarterly regression and support procedures."],deliverables:["Lifecycle requirement and event catalogue","Detailed template/allocation/dependency design","Integration/reporting/exception specification","SIT/UAT/regression and service-transition pack"],tests:["Every lifecycle event","Event correction or cancellation","Multiple concurrent journeys","Task status, notifications and reporting reconciliation"],assessment:"End-to-end consultant judgement, event mapping, exception depth, reusable design and support handover."},
 {id:"ABS-01",area:"Absence",level:"Level 1",name:"Unpaid Personal Leave Type",brief:"Create a simple unpaid absence that records time but does not maintain an entitlement balance.",requirements:["Create an Unpaid Personal Leave category, type and reasons.","Use days as the unit and permit employee self-service entry.","Require a reason and comments for requests longer than three days.","Route requests to the line manager and make the type available only to employees."],deliverables:["Requirement document","Type/reason configuration design","Simple approval design","Unit-test evidence"],tests:["One-day request","Four-day request with required details","Worker outside eligibility","Approve, reject and withdraw"],assessment:"Correct no-entitlement design, type behaviour, basic eligibility and clear testing."},
 {id:"ABS-02",area:"Absence",level:"Level 1",name:"Basic Calendar-Year Annual Leave",brief:"Configure a simple 20-day annual-leave entitlement for full-time UK employees.",requirements:["Create a calendar-year accrual plan with 20 days annual entitlement.","Create and link the Annual Leave absence type.","Automatically enrol eligible UK permanent employees.","Display the plan balance and route requests to the line manager."],deliverables:["Basic BRD","Plan/type/eligibility design","Configuration workbook","Hire and leave test script"],tests:["Eligible new hire enrols","Ineligible contractor does not enrol","Leave reduces balance","Cancellation restores balance"],assessment:"Plan-type relationship, eligibility, balance consumption and transaction lifecycle."},
 {id:"ABS-03",area:"Absence",level:"Level 2",name:"Part-Time Annual Leave Proration",brief:"Extend annual leave so part-time workers receive entitlement according to FTE.",requirements:["Use 25 days as the full-time annual entitlement.","Prorate entitlement by assignment FTE.","Define behaviour for mid-year FTE changes.","Keep a calendar-year plan term and document rounding rules."],deliverables:["Policy interpretation and worked examples","Accrual/proration design","Formula or matrix specification where needed","Boundary-test pack"],tests:["1.0, 0.8 and 0.6 FTE workers","Mid-year FTE increase and decrease","Rounding boundary","Leave consumption after FTE change"],assessment:"Worked calculations, FTE proration, effective-dated change and rounding accuracy."},
 {id:"ABS-04",area:"Absence",level:"Level 2",name:"Sickness with Fit-Note Certification",brief:"Record sickness and request medical evidence when an absence exceeds seven calendar days.",requirements:["Create Sickness type with meaningful reasons and open-ended entry support.","Require a fit-note certification from day eight.","Route the absence to the line manager and send HR an FYI for long absence.","Define how overdue or rejected certificates are followed up."],deliverables:["Requirement and decision table","Type/certification/approval design","Notification content","SIT scenarios"],tests:["7-day and 8-day boundaries","Open-ended sickness then end-date update","Certificate supplied and missing","Retrospective submission"],assessment:"Duration boundary, certification lifecycle, operational ownership and extension behaviour."},
 {id:"ABS-05",area:"Absence",level:"Level 3",name:"Service-Based Annual Leave Bands",brief:"Provide 22, 25 or 28 days according to completed service.",requirements:["Configure service bands: under 3 years = 22; 3–7 years = 25; 8+ years = 28.","Define band change timing and partial-year treatment.","Prorate new hires and part-time workers.","Produce visible worked balance examples for each band."],deliverables:["Detailed requirement and calculation sheet","Accrual band design","Proration specification","SIT/UAT evidence"],tests:["One worker in each band","Exact 3-year and 8-year boundaries","Part-time worker in each band","Service anniversary during the plan year"],assessment:"Band boundaries, service calculation, combined proration and balance reconciliation."},
 {id:"ABS-06",area:"Absence",level:"Level 3",name:"Carryover with March Expiry",brief:"Allow limited annual-leave carryover and expire unused carryover after 31 March.",requirements:["Carry over a maximum of five unused days into the next calendar year.","Expire remaining carried balance after 31 March.","Prevent the total plan balance from exceeding the stated 30-day ceiling.","Define year-end and expiry processing plus employee communication."],deliverables:["Policy-to-rule design","Ceiling/carryover/expiry configuration","Processing calendar","Year-end regression pack"],tests:["0, 3, 5 and 8 unused days","30-day ceiling boundary","Leave consumed before and after expiry","Late year-end processing and reconciliation"],assessment:"Difference between ceiling/carryover/expiry, term processing and boundary evidence."},
 {id:"ABS-07",area:"Absence",level:"Level 4",name:"New-Hire Waiting and Vesting Rules",brief:"Workers accrue annual leave from hire but can use it only after probation.",requirements:["Begin accrual from hire date with new-hire proration.","Apply a three-month vesting period before leave can be used.","Allow HR to record an approved exception with an auditable process.","Define termination before vesting and probation-extension behaviour."],deliverables:["BRD with exception rules","Accrual/vesting design","Adjustment or exception-control design","Positive/negative test pack"],tests:["Accrual before vesting","Request one day before and on vesting date","Probation extension","HR exception and early termination"],assessment:"Accrual-versus-availability distinction, exceptions, dates and auditability."},
 {id:"ABS-08",area:"Absence",level:"Level 4",name:"Occupational Sick-Pay Qualification",brief:"Provide paid sickness entitlement by service and track certification and return-to-work obligations.",requirements:["Create qualification bands for 1 month, 3 months and 6 months paid sick entitlement by service.","Link the sickness type and fit-note certification rules.","Add manager, HRBP and Occupational Health routing based on duration.","Define retrospective entry, absence extension and return-to-work confirmation."],deliverables:["End-to-end requirement and entitlement table","Qualification/type/certification design","Approval and notification design","Combinational SIT/UAT pack"],tests:["Workers in every service band","Duration thresholds","Extension crossing an approval threshold","Missing certificate and return-to-work action"],assessment:"Qualification logic, service bands, evidence, routing and lifecycle complexity."},
 {id:"ABS-09",area:"Absence",level:"Level 5",name:"Time-Off-in-Lieu Accrual and Expiry",brief:"Credit approved overtime as TOIL that must be used within 90 days.",requirements:["Create a TOIL plan and absence type with hours as the unit.","Define how approved credits enter the balance and retain source evidence.","Expire each credit after 90 days and control negative balances.","Support manager approval, manual correction, reporting and reconciliation."],deliverables:["Requirement, process and ownership design","Plan/credit/expiry configuration specification","Adjustment and audit procedure","End-to-end test and reconciliation pack"],tests:["Multiple credits with different expiry dates","Partial consumption","Expiry boundary","Incorrect credit correction and negative-balance prevention"],assessment:"Hours-based design, dated credits, expiry, audit, adjustments and operational reconciliation."},
 {id:"ABS-10",area:"Absence",level:"Level 5",name:"Multi-Population Leave Framework",brief:"Configure annual leave for UK salaried, UK hourly and India employees using controlled variations.",requirements:["Design separate or shared plans based on policy differences and justify the choice.","Vary entitlement, units, eligibility, proration, carryover and approval by population.","Include scheduled processing, HDL opening balances and reporting requirements.","Prepare deployment, conversion, regression and support handover without enterprise-architecture expectations."],deliverables:["Functional BRD and decision matrix","Detailed plan/type/eligibility design","HDL/reporting/processing specifications","Conversion, SIT/UAT/regression and support pack"],tests:["Representative workers from all three populations","New hire, FTE change, transfer and termination","Opening-balance conversion","Approvals, year-end processing and report reconciliation"],assessment:"Consultant-level solution choice, population logic, data setup, end-to-end testing and handover quality."},
 {id:"WFS-01",area:"Workforce Structures",level:"Level 1",name:"Build a Small Retail Workforce",brief:"Create the basic workforce structure for one supermarket with five employees.",requirements:["Create jobs for Store Manager, Cashier and Stock Assistant.","Create one department: Store Operations, and one location: Milton Keynes Store.","Create grades G1–G3 and map each job to a sensible grade.","Hire sample workers using the configured values and explain what each structure represents."],deliverables:["Simple requirement document","Job/grade/department/location data sheet","Configuration screenshots","Basic hire test script"],tests:["Each value is selectable on hire","Correct grade is used","Location address displays","Inactive value cannot be selected after its end date"],assessment:"Can the trainee distinguish job, grade, department and location using the same practical organisation?"},
 {id:"WFS-02",area:"Workforce Structures",level:"Level 2",name:"Job Model or Position Model?",brief:"Recommend and build the correct workforce model for a hospital with controlled nursing vacancies.",requirements:["Compare job and position models against the hospital requirement.","Create Nurse and Senior Nurse jobs with a grade ladder.","Create ward-specific positions with headcount and FTE controls.","Document vacancy, incumbent and replacement behaviour."],deliverables:["Option analysis and recommendation","Position naming/coding standard","Configuration design","Positive and negative tests"],tests:["Fill an open position","Attempt to exceed headcount","Terminate incumbent and reuse position","Promote to a higher position"],assessment:"Model selection, position control, reusable jobs and clear lifecycle reasoning."},
 {id:"WFS-03",area:"Workforce Structures",level:"Level 3",name:"Two-Business-Unit Reference Data",brief:"Design shared and local workforce structures for UK Retail and UK Technology business units.",requirements:["Define Common, Retail and Technology reference data sets.","Share global grades and selected jobs while keeping specialist jobs local.","Create business-unit set assignments.","Demonstrate how the same HR user receives different lists by transaction context."],deliverables:["Reference-data sharing requirement","Set-assignment matrix","Configuration workbook","SIT scenarios"],tests:["Common job appears in both BUs","Retail-only job is hidden from Technology","Set assignment change is verified","Existing worker data remains reportable"],assessment:"Understanding of set-enabled reference data, sharing decisions and transaction behaviour."},
 {id:"WFS-04",area:"Workforce Structures",level:"Level 4",name:"Organisation Restructure",brief:"Move Digital Operations into Technology and create new positions without losing historical accuracy.",requirements:["Future-date department and position changes for 1 January.","Define whether existing departments are renamed, moved, merged or end-dated.","Transfer workers to target assignments with correct actions and reasons.","Assess approvals, security, reporting, integrations and tree impact."],deliverables:["As-is/to-be requirement and structure diagrams","Detailed configuration and transaction design","Impact assessment","SIT/UAT and reconciliation pack"],tests:["Current structure remains valid before 1 January","Future structure takes effect on date","Worker history is preserved","Reports/security/approvals use new structure"],assessment:"Effective dating, restructuring choices, dependency impact and reconciliation."},
 {id:"WFS-05",area:"Workforce Structures",level:"Levels 5–6",name:"Global Workforce Structure Blueprint",brief:"Design an enterprise workforce model for UK, India and UAE across retail, technology and corporate functions.",requirements:["Define global vs local jobs, positions, grades, departments, locations and reference data sets.","Create coding, naming, ownership and effective-dating standards.","Cover position control, grade ladders, action/reason governance and data conversion.","Design security, approvals, payroll, integrations, reporting, cutover and support impacts."],deliverables:["Enterprise BRD and design principles","Logical and detailed workforce-structure design","Data/conversion and governance model","Deployment, regression and service-transition pack"],tests:["Representative country and BU scenarios","Legacy mapping and reconciliation","Cross-country transfer","Role/security and downstream-consumer regression"],assessment:"Enterprise consistency, controlled localisation, dependency management and production governance."},
 {id:"TREE-01",area:"Trees",level:"Level 1",name:"Build a Simple Department Tree",brief:"Create a small school department hierarchy and explain every tree term using it.",requirements:["Use a Department Tree structure and create a clearly named tree code.","Create one version containing School, Academic and Administration roll-ups.","Place English, Maths, Science, Finance and Admissions departments correctly.","Audit, activate and explain root, parent, child, sibling and leaf."],deliverables:["Requirement and hierarchy sketch","Tree vocabulary sheet","Configuration evidence","Basic validation tests"],tests:["Every department appears once","Parent-child roll-up is correct","Audit completes successfully","Active version is effective today"],assessment:"Basic terminology, correct node placement, audit and activation."},
 {id:"TREE-02",area:"Trees",level:"Level 2",name:"Create a Future-Dated Reorganisation",brief:"Move Online Sales from Retail into Digital from 1 January without rewriting history.",requirements:["Retain the current active tree version.","Create a future-dated version under the same tree code.","Move the Online Sales node to its new parent.","Document version dates, status changes and rollback approach."],deliverables:["Current/future hierarchy diagrams","Version and effective-date design","Change steps","Boundary-date tests"],tests:["Old roll-up before 1 January","New roll-up from 1 January","No overlapping active versions","Historical report retains old hierarchy"],assessment:"Tree code stability, versioning, date boundaries and historical reasoning."},
 {id:"TREE-03",area:"Trees",level:"Level 3",name:"Tree Audit and Repair",brief:"Diagnose a department tree containing missing departments, an orphan node and incorrect effective dates.",requirements:["Run and interpret tree audit results.","Identify missing, duplicate/orphan and date-invalid nodes.","Repair the draft version without damaging the active version.","Flatten or refresh hierarchy data where required and reconcile departments."],deliverables:["Defect and root-cause log","Repair design","Before/after configuration evidence","Reconciliation and retest pack"],tests:["All reported defects are resolved","Every active department is accounted for","Audit passes","Representative hierarchy report reconciles"],assessment:"Diagnostic reasoning, safe repair, audit interpretation and completeness."},
 {id:"TREE-04",area:"Trees",level:"Level 4",name:"Department Tree Security Impact",brief:"Use a department hierarchy to support regional HR access and prove that a node move does not create unintended visibility.",requirements:["Define UK Operations and India Operations branches with child departments.","Map the hierarchy to the selected organisation-security design.","Move one department in a future version and assess access impact.","Test authorised, unauthorised and boundary populations plus reporting."],deliverables:["Requirement, personas and access matrix","Tree/security design","Impact and risk assessment","Security/SIT/UAT evidence"],tests:["UK HR sees only the UK branch","India HR sees only India branch","Node move changes access only on effective date","OTBI population agrees with UI security"],assessment:"Consumer-first design, least privilege, date-effective impact and end-to-end proof."},
 {id:"TREE-05",area:"Trees",level:"Levels 5–6",name:"Global Department Hierarchy Governance",brief:"Design a governed global department-tree service used by security, analytics, workforce planning and compensation.",requirements:["Define tree structure, code/version standards, ownership and change calendar.","Design global, regional and functional roll-ups with clear rules for alternative hierarchies.","Create audit, flattening, reconciliation and consumer-registration controls.","Plan migration, future reorganisations, regression, incident handling and operational support."],deliverables:["Enterprise hierarchy BRD and design principles","Tree architecture and governance model","Consumer/impact register","Migration, cutover, regression and support pack"],tests:["Multi-country roll-ups","Current/future versions","Every registered consumer","Failed audit, rollback and emergency-change scenarios"],assessment:"Architecture, governance, consumer traceability, operational resilience and design-authority judgement."},
 {id:"DFF-01",area:"DFF",level:"Level 1",name:"Emergency Contact Verification",brief:"Add a simple worker-level field to record when emergency contact details were last verified.",requirements:["Create a Person DFF date segment named Emergency Contact Verified Date.","Display it globally for all workers and make it optional.","Enable the segment for reporting and expose it on the appropriate person page.","Deploy and validate creation, correction and reporting."],deliverables:["Requirement document with scope and assumptions","DFF configuration design","Field and value-set specification","Unit-test script with evidence"],tests:["Save a valid date","Leave the optional field blank","Correct an existing date","Confirm the value in OTBI"],assessment:"Correct object choice, clear naming, safe deployment and complete basic evidence."},
 {id:"DFF-02",area:"DFF",level:"Level 2",name:"Assignment Equipment Profile",brief:"Capture standard equipment needs against each assignment using controlled lists.",requirements:["Create Assignment DFF segments for Laptop Type, Mobile Required and Accessibility Equipment.","Use appropriate independent value sets and sensible defaulting.","Make Laptop Type required when the segment group is used.","Enable required fields for reporting and document assignment-level ownership."],deliverables:["Business requirement and data dictionary","Value-set design","Configuration workbook","Positive and negative test pack"],tests:["Primary and secondary assignments hold different values","Invalid list value is rejected","Required behaviour works","HDL and OTBI mapping are verified"],assessment:"Correct data level, controlled values, assignment separation and usable documentation."},
 {id:"DFF-03",area:"DFF",level:"Level 3",name:"Country-Specific Worker Compliance",brief:"Show different compliance attributes for UK and India workers without cluttering other users’ pages.",requirements:["Design UK and India contexts on the appropriate worker/assignment flexfield.","UK: Right to Work Review Date and Share Code. India: UAN and Gratuity Nominee Confirmed.","Use date, character and yes/no validations with business-friendly prompts.","Ensure context selection and visibility are correctly controlled."],deliverables:["Context decision and requirement traceability","Segment/value-set matrix","Page and security design","End-to-end test scenarios"],tests:["UK context displays only UK fields","India context displays only India fields","Format and date negatives","Report both contexts without mixing data"],assessment:"Context logic, segment validation, user experience and cross-country reporting."},
 {id:"DFF-04",area:"DFF",level:"Level 4",name:"Temporary Promotion Controls",brief:"Support a temporary promotion action with dates, reason, reference and return-to-grade information.",requirements:["Design action-specific assignment DFF fields for promotion end date, business reason, authorisation reference and return grade.","End Date must be after the effective start date; reason uses a controlled value set.","Fields appear only for the Temporary Promotion action.","Consider Redwood exposure, HDL, audit and downstream reporting."],deliverables:["Full functional requirement document","Solution design with action/context logic","Integration and reporting impact assessment","SIT/UAT test pack"],tests:["Correct action reveals fields","Other actions do not reveal fields","Invalid end date is prevented or handled","HDL, audit and report outputs reconcile"],assessment:"Action scoping, validation realism, lifecycle thinking and test depth."},
 {id:"DFF-05",area:"DFF",level:"Levels 5–6",name:"Global Assignment Compliance Framework",brief:"Design a governed global DFF solution used by HR, integrations and analytics across six countries.",requirements:["Model global and country-context segments with shared naming and ownership standards.","Include sensitive compliance identifiers with role-based visibility requirements.","Define table-validated value sets where values come from governed reference data.","Plan deployment, migration, HDL conversion, reporting, security, support and quarterly regression."],deliverables:["Signed-off BRD and traceability matrix","Detailed functional/configuration design","Data migration and security design","Cutover, regression and operational-support pack"],tests:["Six-country context coverage","Role-based positive and negative security","Legacy conversion reconciliation","Regression across UI, HDL, extracts and analytics"],assessment:"Architecture, governance, security, migration thinking and production-readiness."},
 {id:"EFF-01",area:"EFF",level:"Level 1",name:"Worker Language Record",brief:"Configure a simple extensible record for one language and proficiency detail.",requirements:["Identify the relevant EFF, category and context.","Create segments for Language and Proficiency Level using controlled values.","Allow a single row for this starter requirement.","Deploy, enter data and confirm retrieval."],deliverables:["Short requirement statement","Category/context design","Configuration steps","Basic test evidence"],tests:["Create a valid record","Reject invalid proficiency","Edit the record","Confirm page retrieval"],assessment:"Understanding of category, context, segments and deployment."},
 {id:"EFF-02",area:"EFF",level:"Level 2",name:"Multiple Professional Memberships",brief:"Allow workers to maintain several professional memberships with expiry information.",requirements:["Create a multiple-row context for membership records.","Capture Body, Membership Number, Start Date, Expiry Date and Status.","Define required segments and prevent obviously invalid dates.","Explain what functionally makes each row unique."],deliverables:["Requirement and cardinality definition","EFF context/segment design","Uniqueness and lifecycle rules","Unit-test script"],tests:["Create two memberships","Update only one row","Test invalid date sequence","Retain the other row unchanged"],assessment:"Multi-row modelling, uniqueness, lifecycle and precise evidence."},
 {id:"EFF-03",area:"EFF",level:"Level 3",name:"Certification and Renewal Register",brief:"Build a governed certification register that supports renewal monitoring.",requirements:["Design repeatable certification records under the correct category.","Capture Certification Type, Authority, Number, Issue/Expiry Dates and Renewal Status.","Use table or independent value sets appropriately.","Enable reporting of certifications expiring within 90 days."],deliverables:["Functional requirement document","Category/context/value-set design","Reporting specification","SIT test pack"],tests:["Multiple certifications per person","90-day expiry boundary","Expired and no-expiry cases","Report agrees with source records"],assessment:"Data modelling, validation, reporting logic and boundary testing."},
 {id:"EFF-04",area:"EFF",level:"Level 4",name:"Global Mobility Assignment History",brief:"Maintain multiple mobility records with country, visa and relocation details while protecting sensitive data.",requirements:["Design categories and contexts for Immigration and Relocation information.","Support multiple effective records and defined status transitions.","Restrict immigration identifiers to authorised roles.","Define HDL load/update behaviour using stable source keys."],deliverables:["BRD with personas and security requirements","EFF architecture and lifecycle design","HDL mapping and error-handling design","Security/SIT/UAT pack"],tests:["Multiple mobility rows","Update correct row by source key","Unauthorised user cannot view sensitive context","Extract returns only in-scope records"],assessment:"Category architecture, source keys, security and lifecycle control."},
 {id:"EFF-05",area:"EFF",level:"Levels 5–6",name:"Enterprise Skills Passport",brief:"Create a global, integration-ready employee skills passport consumed by talent, learning and analytics.",requirements:["Model repeatable skills, certifications and experience contexts with governed categories.","Define shared reference values, proficiency scales, evidence and verification status.","Design ownership across employee, manager and HR roles.","Cover conversion, HDL/API integration, security, analytics, retention and support."],deliverables:["Enterprise BRD and process flows","Logical data and detailed EFF design","Integration/security/reporting architecture","Migration, cutover, regression and operating model"],tests:["High-volume multi-row conversion","Role-based create/update/view","Cross-context analytics","Integration retry, duplicate and reconciliation cases"],assessment:"Enterprise modelling, cross-functional governance, non-functional depth and supportability."},
 {id:"KFF-01",area:"KFF",level:"Level 1",name:"Three-Segment Position Code",brief:"Design a simple Position KFF code using Function, Location and Level.",requirements:["Define segment names, order and delimiter.","Create small independent value sets for each segment.","Build and validate sample combinations.","Document the meaning of the concatenated code."],deliverables:["Requirement statement","Structure and segment design","Sample combination catalogue","Basic tests"],tests:["Create a valid combination","Reject invalid segment value","Display concatenated code","Retrieve existing combination"],assessment:"Clear structure, correct value sets and understandable code design."},
 {id:"KFF-02",area:"KFF",level:"Level 2",name:"Country-Specific Job Codes",brief:"Implement Job KFF usage for two countries with governed functional codes.",requirements:["Define whether one structure with instances or separate structures is justified.","Create value sets for Job Family, Specialism and Career Level.","Configure the selected structure instances.","Document how India and UK values are governed."],deliverables:["Requirement and option analysis","Structure-instance design","Value-set catalogue","Configuration/test workbook"],tests:["Valid UK and India combinations","Invalid value by instance","Combination display","Duplicate-combination handling"],assessment:"Sound structure-instance choice and value governance."},
 {id:"KFF-03",area:"KFF",level:"Level 3",name:"Position Code Validation Rules",brief:"Prevent incompatible Business Unit, Function, Location and Level combinations.",requirements:["Extend the Position KFF to four meaningful segments.","Define parent-child or table validations where appropriate.","Create cross-validation rules for prohibited combinations.","Decide whether dynamic insertion should be enabled."],deliverables:["Business rule catalogue","KFF/value-set/CVR design","Governance decision","Positive, negative and boundary tests"],tests:["Each segment value is valid independently","Forbidden cross-segment combination fails","Allowed boundary combination succeeds","Dynamic insertion behaves as designed"],assessment:"Combination-level thinking, CVR accuracy and governance."},
 {id:"KFF-04",area:"KFF",level:"Level 4",name:"Position Code Redesign and Migration",brief:"Redesign an inconsistent legacy position code and migrate active combinations safely.",requirements:["Assess legacy values, duplicates, obsolete codes and downstream consumers.","Propose the target structure and mapping rules.","Define freeze/deploy sequencing and combination migration.","Plan integration, report and reconciliation changes."],deliverables:["As-is/to-be BRD","Gap, impact and mapping document","Detailed migration/cutover design","Regression and reconciliation pack"],tests:["Mapped active combinations","Rejected/unmapped legacy codes","Interface and report compatibility","Pre/post-cutover reconciliation"],assessment:"Impact analysis, migration control, traceability and cutover realism."},
 {id:"KFF-05",area:"KFF",level:"Levels 5–6",name:"Enterprise Job and Position Coding Standard",brief:"Create a multi-country KFF governance standard that supports HR operations, finance integration and workforce analytics.",requirements:["Define global segments, local variation, labels, qualifiers and structure instances.","Design controlled value ownership and request/approval for new combinations.","Address dynamic insertion, end-dating and reuse policies.","Cover conversion, interfaces, security, reporting, cutover and operating governance."],deliverables:["Enterprise requirements and design principles","KFF architecture and governance model","Integration/data/reporting specifications","Migration, cutover, regression and service-transition pack"],tests:["Representative countries and business units","Combination request governance","End-dated value behaviour","End-to-end payroll/finance/analytics consumers"],assessment:"Strategic design, enterprise governance, consumer impact and production ownership."},
 {id:"APP-01",area:"Approvals",level:"Level 1",name:"Simple Learning Request",brief:"Route an external course request to the employee’s line manager.",requirements:["Trigger on employee-submitted external learning requests.","Resolve the current line manager as approver.","Auto-approve manager-submitted requests or document the chosen self-approval control.","Provide clear approval notification content."],deliverables:["Requirement document","Simple approval design","Notification fields list","Unit tests"],tests:["Employee submission","Manager submission","Missing manager","Approve and reject outcomes"],assessment:"Basic trigger, participant resolution and clear expected results."},
 {id:"APP-02",area:"Approvals",level:"Level 2",name:"High-Cost Learning Approval",brief:"Add HRBP approval when external course cost exceeds £2,000.",requirements:["Route all requests to line manager.","Add HRBP serially when cost is greater than £2,000.","Define behaviour at exactly £2,000 and currency assumptions.","Prevent creator self-approval."],deliverables:["Business rules and assumptions","Approval flow design","Boundary-test script","Notification design"],tests:["£1,999.99, £2,000 and £2,000.01","HRBP submits request","Missing HRBP","Rejection at each stage"],assessment:"Threshold accuracy, serial routing, self-approval and boundary testing."},
 {id:"APP-03",area:"Approvals",level:"Level 3",name:"Long-Term Absence Review",brief:"Route sickness absence based on duration, retrospective entry and worker population.",requirements:["≤5 days: Line Manager; 6–20: Line Manager then HRBP; ≥20: add Occupational Health.","Retrospective submissions always require HRBP.","Clinical Operations workers send FYI to Clinical HR Lead.","Define missing participant and extension behaviour."],deliverables:["BRD and decision table","BPM rule design","Participant-resolution document","SIT test pack"],tests:["5/6/20/21-day boundaries","Retrospective short absence","Clinical Ops FYI","Extension from 10 to 25 days"],assessment:"Rule decomposition, combined conditions, rerouting and test coverage."},
 {id:"APP-04",area:"Approvals",level:"Level 4",name:"India-to-UK Global Transfer",brief:"Design a transfer approval chain with conditional specialists, duplicates and self-approval controls.",requirements:["Base chain: current LM, current HRBP, receiving LM, receiving HRBP.","Grade 7+ adds HR Director; salary increase >15% adds Compensation Manager.","Legal Employer change adds Global Mobility; BU-only change does not.","Remove duplicate managers/HRBPs and prevent receiving-HRBP self-approval."],deliverables:["Full requirement and question log","Decision table and participant design","BPM configuration design","Comprehensive SIT/UAT pack"],tests:["Every threshold and rule independently","Multiple rules together","Same manager and same HRBP","Receiving HRBP initiation and missing actors"],assessment:"End-to-end logic, duplicate/self controls, traceability and combinational tests."},
 {id:"APP-05",area:"Approvals",level:"Levels 5–6",name:"Global Compensation Change Framework",brief:"Create an enterprise approval framework for promotions, market adjustments and off-cycle salary changes.",requirements:["Vary routing by action, grade, increase percentage, country and management hierarchy.","Add Compensation, Finance, HR Director and executive approvers under defined conditions.","Design serial/parallel stages, FYIs, self-approval, delegation, escalation and expiry.","Cover mass transactions, audit, notification, support and quarterly regression."],deliverables:["Enterprise BRD, RACI and decision catalogue","Approval architecture and detailed rule design","Security, notification and exception design","SIT/UAT/regression, deployment and support pack"],tests:["Actions and threshold boundaries","Country and currency variants","Delegation/escalation/missing participants","Mass processing, audit and regression"],assessment:"Enterprise rule architecture, exception handling, operational resilience and auditability."}
];

export default function Home(){
 const[moduleId,setModuleId]=useState("otbi"),[active,setActive]=useState(0),[done,setDone]=useState<Record<string,number[]>>({}),[foundationDone,setFoundationDone]=useState<Record<string,number[]>>({}),[savedProgress,setSavedProgress]=useState<SavedProgress[]>([]),[traineeMode,setTraineeMode]=useState(false),[answer,setAnswer]=useState<number|null>(null),[revealed,setRevealed]=useState(false),[lab,setLab]=useState("dff"),[taskArea,setTaskArea]=useState("OTBI"),[taskLevel,setTaskLevel]=useState("All"),[openTask,setOpenTask]=useState("OTBI-01"),[extraFunctional,setExtraFunctional]=useState(false),[foundationTab,setFoundationTab]=useState("Curriculum"),[foundationUnit,setFoundationUnit]=useState(0),[foundationLesson,setFoundationLesson]=useState(0),[openAssessment,setOpenAssessment]=useState("FND-01"),[techArea,setTechArea]=useState("Technical HDL"),[techLevel,setTechLevel]=useState("All"),[openTechTask,setOpenTechTask]=useState("THDL-01"),[extraTechnical,setExtraTechnical]=useState(false),[techLearn,setTechLearn]=useState("OIC");
 const mod=modules.find(m=>m.id===moduleId)!;const rawLesson=mod.lessons[active];const lesson={...rawLesson,example:personaText(rawLesson.example,moduleId),check:{...rawLesson.check,q:personaText(rawLesson.check.q,moduleId)}};const completed=done[moduleId]||[];const progress=mod.lessons.length?Math.round(completed.length/mod.lessons.length*100):0;
 useEffect(()=>{const x=localStorage.getItem("oracle-academy-v2"),f=localStorage.getItem("oracle-foundations-v1");if(x)setDone(JSON.parse(x));if(f)setFoundationDone(JSON.parse(f));fetch("/api/trainee").then(r=>r.ok?r.json():null).then(d=>{if(d?.profile){setTraineeMode(true);setSavedProgress(d.progress||[])}}).catch(()=>{})},[]);
 function choose(id:string){const m=modules.find(x=>x.id===id)!;if(!m.lessons.length)return;setModuleId(id);setActive(0);setAnswer(null);setRevealed(false);setTimeout(()=>document.getElementById("classroom")?.scrollIntoView({behavior:"smooth"}),50)}
 function selectLesson(i:number){if(traineeMode&&i>0&&!completed.includes(i-1))return;setActive(i);setAnswer(null);setRevealed(false)}
 function complete(){const next={...done,[moduleId]:completed.includes(active)?completed.filter(x=>x!==active):[...completed,active]};setDone(next);localStorage.setItem("oracle-academy-v2",JSON.stringify(next));if(!completed.includes(active))fetch("/api/progress",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({itemType:"lesson",itemId:`LESSON-${moduleId.toUpperCase()}-${active+1}`,area:mod.title,title:lesson.title,level:null,status:"completed",notes:"Lesson completed in the sequential learning path."})}).catch(()=>{})}
 function foundationUnlocked(unit:number,lesson:number){if(!traineeMode)return true;const unitDone=foundationDone[foundationUnits[unit].id]||[];if(lesson>0)return unitDone.includes(lesson-1);if(unit===0)return true;const previous=foundationUnits[unit-1],previousDone=foundationDone[previous.id]||[];return previousDone.length===previous.lessons.length}
 function openFoundation(unit:number,lesson=0,tab="Training"){if(!foundationUnlocked(unit,lesson))return;setFoundationUnit(unit);setFoundationLesson(lesson);setFoundationTab(tab)}
 function completeFoundation(){const unit=foundationUnits[foundationUnit],current=foundationDone[unit.id]||[];if(current.includes(foundationLesson))return;const next={...foundationDone,[unit.id]:[...current,foundationLesson]};setFoundationDone(next);localStorage.setItem("oracle-foundations-v1",JSON.stringify(next));fetch("/api/progress",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({itemType:"lesson",itemId:`FND-${foundationUnit+1}-${foundationLesson+1}`,area:"Foundations",title:unit.lessons[foundationLesson].title,level:Math.min(5,foundationUnit+1),status:"completed",notes:"Foundation lesson completed in sequence."})}).catch(()=>{})}
 const taskDone=(id:string)=>savedProgress.some(p=>p.itemId===id&&(p.status==="completed"||p.status==="reviewed"));
 const taskLocked=(task:TraineeTask,sequence:TraineeTask[])=>{if(!traineeMode||task.id.includes("-X"))return false;const index=sequence.findIndex(t=>t.id===task.id);return index>0&&!taskDone(sequence[index-1].id)};
 return <main>
  <header className="topbar"><a className="brand" href="#top"><img className="chc-logo" src="/chc-logo.png" alt="CHC"/><span><b>CHC · ORACLE HCM</b><small>ACADEMY</small></span></a><nav><a href="/pathways">Pathways</a><a href="#curriculum">Curriculum</a><a href="#task-bank">Task bank</a><a href="/task-workspace">Submissions</a><a href="/interview">Mock interviews</a><a href="/names">Our names</a><a href="/trainer">Trainer</a></nav><div className="d-flex align-items-center gap-2">{traineeMode?<a className="profile" href="/dashboard" aria-label="Open my training dashboard">MY</a>:<a className="btn btn-sm btn-outline-dark fw-semibold" href="/login"><i className="bi bi-box-arrow-in-right me-1"></i>Sign in</a>}</div></header>
  <section className="academy-hero" id="top"><div className="eyebrow"><span>CHC</span><i/><span>ORACLE HCM FUNCTIONAL ACADEMY</span></div><div className="academy-hero-grid"><div><h1>Understand Oracle.<br/><em>Then configure.</em></h1><p>A structured programme from ERP fundamentals and environment lifecycle through enterprise structures, workforce setup, trees and specialist configuration.</p><div className="hero-actions"><a className="primary" href="#foundation-track">Start with foundations <span>↓</span></a><a className="trainee-login" href="/dashboard">Register / track training →</a></div></div><div className="hero-stack foundation-stack"><div className="stack-label">FOUNDATION LEARNING JOURNEY</div>{foundationUnits.slice(0,5).map((u,i)=>{const locked=!foundationUnlocked(i,0);return <button disabled={locked} className={locked?"sequence-locked":""} key={u.id} onClick={()=>{openFoundation(i);document.getElementById("foundation-track")?.scrollIntoView({behavior:"smooth"})}}><span className="path-number">{locked?"🔒":String(i+1).padStart(2,"0")}</span><span><b>{u.title}</b><small>{locked?"Complete the previous unit":`${u.lessons.length} lessons · ${u.duration}`}</small></span><em>{locked?"LOCKED":i===0?"START HERE":"→"}</em></button>})}</div></div></section>
  <section className="foundation-track" id="foundation-track"><SectionHead n="00" over="START HERE" title="Oracle HCM Foundations"><p>Curriculum → syllabus → guided training → team assessments.</p></SectionHead><FoundationProcessFlows/><div className="foundation-tabs">{["Curriculum","Syllabus","Training","Assessments"].map(t=><button className={foundationTab===t?"active":""} onClick={()=>setFoundationTab(t)} key={t}>{t}</button>)}</div>
   {foundationTab==="Curriculum"&&<div className="roadmap">{foundationUnits.map((u,i)=>{const locked=!foundationUnlocked(i,0);return <button className={locked?"sequence-locked":""} disabled={locked} key={u.id} onClick={()=>openFoundation(i,0,"Syllabus")}><span>{locked?"🔒":String(i+1).padStart(2,"0")}</span><div><small>UNIT {i+1} · {u.duration.toUpperCase()}</small><h3>{u.title}</h3><p>{u.outcome}</p></div><em>{locked?"PREVIOUS UNIT FIRST":i<foundationUnits.length-1?"↓":"✓"}</em></button>})}</div>}
   {foundationTab==="Syllabus"&&<div className="syllabus-layout"><aside>{foundationUnits.map((u,i)=>{const locked=!foundationUnlocked(i,0);return <button disabled={locked} className={`${foundationUnit===i?"active":""} ${locked?"sequence-locked":""}`} onClick={()=>openFoundation(i,0,"Syllabus")} key={u.id}><span>{locked?"🔒":String(i+1).padStart(2,"0")}</span><b>{u.title}</b><small>{locked?"Complete the previous unit":`${u.lessons.length} lessons`}</small></button>})}</aside><article><small>UNIT {foundationUnit+1} · SEQUENTIAL SYLLABUS</small><h2>{foundationUnits[foundationUnit].title}</h2><p className="unit-outcome"><b>OUTCOME</b>{foundationUnits[foundationUnit].outcome}</p>{foundationUnits[foundationUnit].lessons.map((l,i)=>{const locked=!foundationUnlocked(foundationUnit,i),finished=(foundationDone[foundationUnits[foundationUnit].id]||[]).includes(i);return <div className={`syllabus-row ${locked?"sequence-locked":""}`} key={l.title}><span>{finished?"✓":locked?"🔒":String(i+1).padStart(2,"0")}</span><div><b>{l.title}</b><p>{locked?"Complete the previous lesson to unlock this chapter.":l.summary}</p></div><button disabled={locked} onClick={()=>openFoundation(foundationUnit,i)}>{finished?"REVIEW →":locked?"LOCKED":"OPEN →"}</button></div>})}</article></div>}
   {foundationTab==="Training"&&<div className="training-layout"><aside><small>SELECT UNIT</small>{foundationUnits.map((u,i)=>{const locked=!foundationUnlocked(i,0);return <button disabled={locked} className={`${foundationUnit===i?"active":""} ${locked?"sequence-locked":""}`} onClick={()=>openFoundation(i)} key={u.id}>{locked?"🔒":String(i+1).padStart(2,"0")} · {u.title}</button>})}</aside><article className="training-content"><div className="training-meta"><span>UNIT {foundationUnit+1} · CHAPTER {foundationLesson+1}</span><span>{foundationUnits[foundationUnit].duration.toUpperCase()}</span></div><h2>{foundationUnits[foundationUnit].lessons[foundationLesson].title}</h2><p className="training-summary">{foundationUnits[foundationUnit].lessons[foundationLesson].summary}</p><LessonVideo topic={`${foundationUnits[foundationUnit].title}: ${foundationUnits[foundationUnit].lessons[foundationLesson].title}`} video={foundationVideos[foundationUnits[foundationUnit].id]}/>{foundationUnits[foundationUnit].id==="employee"&&foundationLesson===0&&<EmployeeLifecycleMap/>}<div className="training-points">{foundationUnits[foundationUnit].lessons[foundationLesson].points.map((x,i)=><div key={x}><span>{String(i+1).padStart(2,"0")}</span><p>{x}</p></div>)}</div><div className="training-example"><small>PRACTICAL ORACLE HCM EXAMPLE</small><p>{foundationUnits[foundationUnit].lessons[foundationLesson].example}</p></div><button className="foundation-complete" disabled={(foundationDone[foundationUnits[foundationUnit].id]||[]).includes(foundationLesson)} onClick={completeFoundation}>{(foundationDone[foundationUnits[foundationUnit].id]||[]).includes(foundationLesson)?"✓ Chapter complete":"Complete chapter and unlock next →"}</button><div className="lesson-nav"><button disabled={foundationLesson===0} onClick={()=>setFoundationLesson(foundationLesson-1)}>← Previous</button><span>{foundationLesson+1} / {foundationUnits[foundationUnit].lessons.length}</span><button disabled={foundationLesson===foundationUnits[foundationUnit].lessons.length-1||!foundationUnlocked(foundationUnit,foundationLesson+1)} onClick={()=>setFoundationLesson(foundationLesson+1)}>Next →</button></div></article><aside className="lesson-menu"><small>UNIT LESSONS</small>{foundationUnits[foundationUnit].lessons.map((l,i)=>{const locked=!foundationUnlocked(foundationUnit,i);return <button disabled={locked} className={`${foundationLesson===i?"active":""} ${locked?"sequence-locked":""}`} onClick={()=>openFoundation(foundationUnit,i)} key={l.title}><span>{(foundationDone[foundationUnits[foundationUnit].id]||[]).includes(i)?"✓":locked?"🔒":String(i+1).padStart(2,"0")}</span>{l.title}</button>})}</aside></div>}
   {foundationTab==="Assessments"&&<div className="foundation-assessments"><div className="assessment-intro"><span>10</span><div><h3>Team assessments</h3><p>Progressive evidence-based assignments from Level 1 to Level 6. Each requires a tangible document, model or presentation—not a memorised answer.</p></div></div>{foundationAssessments.map(a=><article className={openAssessment===a.id?"open":""} key={a.id}><button onClick={()=>setOpenAssessment(openAssessment===a.id?"":a.id)}><span>{a.id}</span><small>{a.level.toUpperCase()}</small><b>{a.name}</b><em>{openAssessment===a.id?"−":"+"}</em></button>{openAssessment===a.id&&<div><p>{a.brief}</p><span>SUBMISSION: Requirement interpretation · Design rationale · Evidence · Reviewer presentation</span></div>}</article>)}</div>}
   <section className="community-starter"><div><small>FOUNDATION PRACTICE · ORACLE COMMUNITY</small><h3>Go beyond the training instance</h3><p>Oracle consultants must know how to find current evidence, learn from customer experience and ask responsible questions. Community participation is part of the curriculum—not optional browsing.</p></div><div className="community-actions"><a href={oracleLinks.connect} target="_blank" rel="noreferrer"><b>01</b><span>Open Customer Connect<small>Oracle cloud community</small></span></a><a href={oracleLinks.register} target="_blank" rel="noreferrer"><b>02</b><span>Registration guide<small>Existing Oracle Account</small></span></a><a href={oracleLinks.connectVideo} target="_blank" rel="noreferrer"><b>03</b><span>Watch: connect with customers<small>YouTube introduction</small></span></a><a href={oracleLinks.community} target="_blank" rel="noreferrer"><b>04</b><span>Enter the HCM community<small>Follow relevant categories</small></span></a></div><aside><b>COMMUNITY RULE</b>Search first. Mask all client and personal data. State the release and steps. Test advice in the training instance. Return and document what actually solved the problem.</aside></section>
  </section>
  <section className="curriculum" id="curriculum"><SectionHead n="01" over="CURRICULUM" title="Build judgement in layers"><p>Move from shared HCM foundations into functional modules, reporting, integrations and controlled administration.</p></SectionHead><div className="module-grid">{curriculumModules.map(m=><button className={`module-card ${m.id===moduleId?"selected":""} ${!m.lessons.length?"locked":""}`} key={m.id} onClick={()=>choose(m.id)}><div><span className={`module-icon ${m.color}`}>{m.label}</span><em>{m.status}</em></div><h3>{m.title}</h3><p>{m.sub}</p><footer><span>{m.lessons.length?`${m.lessons.length} LESSONS · ${m.time}`:m.time.toUpperCase()}</span><b>{m.lessons.length?"OPEN →":"PLANNED"}</b></footer></button>)}</div></section>
  <section className="compare"><div><small>THE FIRST DECISION</small><h2>DFF, EFF or KFF?</h2><p>The choice is about the shape and purpose of the data—not which acronym sounds closest.</p></div><div className="compare-table"><div className="compare-row head"><span></span><b>DFF</b><b>EFF</b><b>KFF</b></div><Compare l="Primary purpose" a="Describe an existing record" b="Extend with richer records" c="Build an identifying code"/><Compare l="Rows" a="Usually one set per context" b="Can support multiple rows" c="One validated combination"/><Compare l="Typical example" a="Uniform size" b="Professional licences" c="Position code"/><Compare l="Core design idea" a="Context" b="Category + context" c="Structure + instance"/></div></section>
  <section className="classroom" id="classroom"><SectionHead n="02" over={`${mod.label} · SEQUENTIAL LEARNING PATH`} title={mod.title}><div className="progress"><div><b>{progress}%</b><span>{completed.length} of {mod.lessons.length} complete</span></div><i><em style={{width:`${progress}%`}}/></i></div></SectionHead><div className="class-layout"><aside>{mod.lessons.map((l,i)=>{const locked=traineeMode&&i>0&&!completed.includes(i-1);return <button disabled={locked} className={`${active===i?"active":""} ${locked?"sequence-locked":""}`} onClick={()=>selectLesson(i)} key={l.title}><span className={completed.includes(i)?"done":""}>{completed.includes(i)?"✓":locked?"🔒":String(i+1).padStart(2,"0")}</span><span><small>{locked?"COMPLETE PREVIOUS LESSON":l.stage}</small><b>{l.title}</b><em>{l.time}</em></span></button>})}</aside><article className="lesson-panel"><div className="lesson-meta"><span>{lesson.stage}</span><span>{lesson.time.toUpperCase()}</span></div><h2>{lesson.title}</h2><p className="objective"><b>Learning objective</b>{lesson.objective}</p><LessonVideo topic={`${mod.title}: ${lesson.title}`} video={lessonVideos[mod.id]}/><div className="topic-grid">{lesson.topics.map((t,i)=><div key={t}><span>{String(i+1).padStart(2,"0")}</span>{t}</div>)}</div><div className="judgement"><span>✦</span><p><b>DESIGN JUDGEMENT</b>{lesson.judgement}</p></div><div className="worked"><small>WORKED EXAMPLE</small><p>{lesson.example}</p></div><button className={completed.includes(active)?"complete":"primary"} onClick={complete}>{completed.includes(active)?"✓ Lesson complete":"Mark complete and unlock next →"}</button></article><aside className="knowledge"><small>CHECK YOUR UNDERSTANDING</small><h3>{lesson.check.q}</h3>{lesson.check.o.map((o,i)=><button className={`${answer===i?"chosen":""} ${revealed&&i===lesson.check.a?"correct":""}`} key={o} onClick={()=>!revealed&&setAnswer(i)}><span>{String.fromCharCode(65+i)}</span>{o}</button>)}<button className="check" disabled={answer===null} onClick={()=>setRevealed(true)}>Check answer</button>{revealed&&<p className={answer===lesson.check.a?"feedback right":"feedback"}><b>{answer===lesson.check.a?"Correct.":"Review this."}</b>{lesson.check.why}</p>}</aside></div><ResourcePanel topic={topicLabel[mod.id]||mod.title}/></section>
  <section className="decision-lab" id="decision-lab"><SectionHead n="03" over="PRACTICE" title="Choose the right flexfield"><p>Inspect the requirement. Defend the data model before configuring anything.</p></SectionHead><div className="lab-case"><div><small>REQUIREMENT 01 · WORKER DATA</small><h2>“Record every professional certification a worker holds, including issuing body, number, issue date, expiry date and status.”</h2><div className="clues"><span>↻ Multiple records</span><span>◷ Lifecycle dates</span><span>▦ Structured attributes</span></div></div><div className="lab-options">{[{id:"dff",t:"DFF",s:"Add descriptive fields"},{id:"eff",t:"EFF",s:"Create repeatable records"},{id:"kff",t:"KFF",s:"Build an identifying code"}].map(x=><button className={lab===x.id?"selected":""} onClick={()=>setLab(x.id)} key={x.id}><span>{x.t}</span><p><b>{x.s}</b>{x.id==="eff"?"Supports multiple structured rows with their own lifecycle.":x.id==="dff"?"Better for a single set of extra attributes.":"Intended for meaningful code combinations."}</p></button>)}<div className={`lab-verdict ${lab==="eff"?"right":""}`}><b>{lab==="eff"?"✓ Strong design choice":"↻ Reconsider the data shape"}</b><p>{lab==="eff"?"An EFF can model each certification as a separate governed record. Define uniqueness and expiry behaviour before configuration.":"The requirement needs multiple repeatable records, not one attribute set or an identifying code."}</p></div></div></div></section>
  <section className="task-bank" id="task-bank"><SectionHead n="04" over="TRAINEE ASSIGNMENTS" title="End-to-end Task Bank"><p>Buildable requirements in controlled sequence. For signed-in trainees, each task unlocks after the previous task is reviewed or completed.</p></SectionHead><div className="task-toolbar"><div>{["ORC","Oracle Learn","Talent","OTBI","Alert Composer","HDL/HSDL","Fast Formula","Work Schedules","Operations","Redwood/VBS","BIP/Extracts","Security/AOR","Checklists","Absence","Workforce Structures","Trees","DFF","EFF","KFF","Approvals"].map(a=><button className={taskArea===a?"active":""} onClick={()=>{setTaskArea(a);setOpenTask(traineeTasks.find(t=>t.area===a)!.id);setExtraFunctional(false)}} key={a}>{a==="Trees"?"Department Trees":a}</button>)}</div><select aria-label="Filter by level" value={taskLevel} onChange={e=>{setTaskLevel(e.target.value);setExtraFunctional(false)}}><option>All</option><option>Level 1</option><option>Level 2</option><option>Level 3</option><option>Level 4</option><option>Level 5</option><option>Levels 5–6</option></select></div><ResourcePanel compact topic={taskArea}/>{(()=>{const sequence=traineeTasks.filter(t=>t.area===taskArea),base=sequence.filter(t=>taskLevel==="All"||t.level===taskLevel),list=extraFunctional?[...base,...extraTasks(taskArea,taskLevel)]:base;return <><div className="task-list">{list.map(t=>{const locked=taskLocked(t,sequence);return <article className={`task-card ${openTask===t.id?"open":""} ${locked?"sequence-locked":""}`} key={t.id}><button disabled={locked} className="task-summary" onClick={()=>setOpenTask(openTask===t.id?"":t.id)}><span className="task-id">{locked?"🔒 LOCKED":`TASK ${t.id}`}</span><span><small>{locked?"COMPLETE THE PREVIOUS TASK":t.level.toUpperCase()}</small><b>{t.name}</b><p>{locked?"Your trainer must review or approve the previous task before this one opens.":t.brief}</p></span><em>{locked?"":openTask===t.id?"−":"+"}</em></button>{openTask===t.id&&!locked&&<div className="task-detail"><TaskColumn title="BUSINESS REQUIREMENTS" items={t.requirements}/><TaskColumn title="MANDATORY DELIVERABLES" items={t.deliverables}/><TaskColumn title="MINIMUM TEST COVERAGE" items={t.tests}/><div className="assessment"><small>ASSESSMENT FOCUS</small><p>{t.assessment}</p></div></div>}</article>})}</div><div className="task-extension"><div><small>NEED MORE PRACTICE AT THIS LEVEL?</small><b>Add five structured {taskLevel==="All"?"current-level":taskLevel} challenges</b><p>Regional variation, conversion, exception handling, reconciliation, and release/support.</p></div><button onClick={()=>setExtraFunctional(!extraFunctional)}>{extraFunctional?"Remove extra tasks":"＋ Add 5 more tasks"}</button></div>{taskArea==="Approvals"&&<AiPracticeGenerator signedIn={traineeMode} unlocked={["APP-01","APP-02","APP-03","APP-04","APP-05"].every(taskDone)}/>}</>})()}</section>
  <section className="technical-curriculum" id="technical-curriculum"><SectionHead n="05" over="TECHNICAL CURRICULUM" title="Complete the developer toolkit"><p>Eight additional areas for a practical 2–4 year technical profile. Each lesson explains what the tool is for before asking trainees to build.</p></SectionHead><div className="tech-learn-tabs">{technicalLearningAreas.map(a=><button key={a.area} className={techLearn===a.area?"active":""} onClick={()=>setTechLearn(a.area)}>{a.label}</button>)}</div>{technicalLearningAreas.filter(a=>a.area===techLearn).map(a=><div className="tech-learn-panel" key={a.area}><div className="tech-explain"><small>PLAIN-LANGUAGE EXPLANATION</small><h3>{a.label}</h3><p>{a.plain}</p><div><small>SIMPLE REAL-LIFE EXAMPLE</small><p>{a.example}</p></div><aside><b>WATCH OUT</b>{a.watch}</aside></div><div className="tech-lesson-list"><small>5-LESSON CLASS SYLLABUS</small>{a.lessons.map((l,i)=><article key={l.title}><span>{String(i+1).padStart(2,"0")}</span><div><b>{l.title}</b><p>{l.focus}</p></div></article>)}</div></div>)}<ResourcePanel compact topic={techLearn}/></section>
  <section className="task-bank technical-bank" id="technical-bank"><SectionHead n="06" over="TECHNICAL TRACK" title="Technical Build Lab"><p>One hundred and fifty technical requirements, sequenced from Level 1 through Level 5 with optional five-task extension packs.</p></SectionHead><div className="technical-note"><span>TECH</span><p><b>Separate from functional basics</b>These assignments require technical mappings, payloads or code/configuration evidence, failure handling and production-support documentation.</p></div><div className="task-toolbar"><div>{technicalTaskSpecs.map(s=>s.area).map(a=><button className={techArea===a?"active":""} onClick={()=>{setTechArea(a);setOpenTechTask(technicalTasks.find(t=>t.area===a)!.id);setExtraTechnical(false)}} key={a}>{a.replace("Technical ","")}</button>)}</div><select aria-label="Filter technical tasks by level" value={techLevel} onChange={e=>{setTechLevel(e.target.value);setExtraTechnical(false)}}><option>All</option><option>Level 1</option><option>Level 2</option><option>Level 3</option><option>Level 4</option><option>Level 5</option></select></div><ResourcePanel compact topic={techArea}/>{(()=>{const sequence=technicalTasks.filter(t=>t.area===techArea),base=sequence.filter(t=>techLevel==="All"||t.level===techLevel),list=extraTechnical?[...base,...extraTasks(techArea,techLevel,true)]:base;return <><div className="task-list">{list.map(t=>{const locked=taskLocked(t,sequence);return <article className={`task-card ${openTechTask===t.id?"open":""} ${locked?"sequence-locked":""}`} key={t.id}><button disabled={locked} className="task-summary" onClick={()=>setOpenTechTask(openTechTask===t.id?"":t.id)}><span className="task-id">{locked?"🔒 LOCKED":`TASK ${t.id}`}</span><span><small>{locked?"COMPLETE THE PREVIOUS TASK":t.level.toUpperCase()}</small><b>{t.name}</b><p>{locked?"Your trainer must review or approve the previous task before this one opens.":t.brief}</p></span><em>{locked?"":openTechTask===t.id?"−":"+"}</em></button>{openTechTask===t.id&&!locked&&<div className="task-detail"><TaskColumn title="TECHNICAL REQUIREMENTS" items={t.requirements}/><TaskColumn title="MANDATORY DELIVERABLES" items={t.deliverables}/><TaskColumn title="MINIMUM TEST COVERAGE" items={t.tests}/><div className="assessment"><small>ASSESSMENT FOCUS</small><p>{t.assessment}</p></div></div>}</article>})}</div><div className="task-extension"><div><small>LEVEL EXTENSION PACK</small><b>Add five technical build challenges</b><p>Each adds requirements, design, build evidence, UAT and production-support thinking.</p></div><button onClick={()=>setExtraTechnical(!extraTechnical)}>{extraTechnical?"Remove extra tasks":"＋ Add 5 more tasks"}</button></div></>})()}</section>
  <section className="next-module"><span className="module-icon blue">TECH</span><div><small>TECHNICAL TRACK · LEVELS 1–5</small><h2>Oracle HCM Technical Build Lab</h2><p>15 areas · 150 technical requirements · 275 tasks across the academy</p></div><a href="#technical-bank">OPEN TECHNICAL TASKS →</a></section>
  <footer className="site-footer"><div className="brand inverse"><img className="chc-logo" src="/chc-logo.png" alt="CHC"/><span><b>CHC · ORACLE HCM</b><small>ACADEMY</small></span></div><p>Learn the design. Then configure.</p><button onClick={()=>scrollTo({top:0,behavior:"smooth"})}>BACK TO TOP ↑</button></footer>
 </main>
}
function EmployeeLifecycleMap(){const stages=[
 {n:"01",phase:"SOURCE",event:"Jenny discovers a role and joins the talent pool",modules:"Oracle Recruiting Cloud (ORC)",result:"Prospect or candidate profile"},
 {n:"02",phase:"RECRUIT & SELECT",event:"Jenny applies, interviews and receives an offer",modules:"Oracle Recruiting Cloud (ORC)",result:"Application, selection and accepted offer"},
 {n:"03",phase:"HIRE",event:"Jenny becomes an employee",modules:"ORC handoff + Global HR / Core HR",result:"Person, work relationship and assignment"},
 {n:"04",phase:"ONBOARD",event:"Jenny completes her joining activities",modules:"Journeys + Checklists",result:"Tasks, documents and introductions"},
 {n:"05",phase:"WORK, TIME & LEAVE",event:"Jenny works, records time and requests leave",modules:"Core HR · Time and Labor · Absence",result:"Assignment, time entries and absence balances"},
 {n:"06",phase:"PAY, BENEFITS & REWARD",event:"Jenny enrols, is rewarded and gets paid",modules:"Benefits · Workforce Compensation · Payroll",result:"Enrolments, awards and payroll result"},
 {n:"07",phase:"LEARN & GROW",event:"Jenny builds skills and plans her career",modules:"Learning + Career Development",result:"Learning history, skills and career plans"},
 {n:"08",phase:"PERFORM & PROMOTE",event:"Jenny agrees goals, is reviewed and promoted",modules:"Goals · Performance · Core HR",result:"Goals, rating and assignment promotion"},
 {n:"09",phase:"TALENT & SUCCESSION",event:"Leaders assess Jenny’s potential and readiness",modules:"Talent Review + Succession Planning",result:"Talent ratings and succession plans"},
 {n:"10",phase:"MOVE, EXIT OR REHIRE",event:"Jenny transfers, leaves or later returns",modules:"Core HR · Journeys · Payroll",result:"Assignment change, termination or rehire"}
 ];return <section className="employee-lifecycle-map" aria-label="Employee lifecycle and Oracle Fusion module process flow"><div className="analytics-layer"><span>COMMON ANALYTICS LAYER</span><b>FDI</b><p>Prebuilt Fusion application insights</p><i>+</i><b>OAC</b><p>Broader governed analytics and visualisation</p></div><div className="lifecycle-caption"><small>FOLLOW ONE EMPLOYEE: JENNY</small><b>Prospect → candidate → worker → contributor → talent → leaver or rehire</b></div><div className="lifecycle-scroll"><div className="lifecycle-stages">{stages.map((s,i)=><div className="lifecycle-stage" key={s.n}><article><span>{s.n}</span><small>{s.phase}</small><h4>{s.event}</h4><b>{s.modules}</b><p>{s.result}</p></article>{i<stages.length-1&&<em aria-hidden="true">→</em>}</div>)}</div></div><div className="lifecycle-ownership"><b>Do not confuse the modules</b><p><strong>ORC</strong> manages the candidate journey. <strong>Core HR</strong> owns the worker and records promotions or transfers. <strong>Benefits</strong> manages enrolment. <strong>Workforce Compensation</strong> plans salary and awards. <strong>Payroll</strong> calculates and pays the result.</p></div><div className="integration-layer"><span>COMMON INTEGRATION LAYER</span><b>Oracle Integration (OIC)</b><p>Moves and orchestrates required data between every lifecycle stage, other Oracle Cloud modules and approved external systems.</p></div><div className="lifecycle-key"><p><b>Business event</b> The main activity in Jenny’s journey.</p><p><b>Green module strip</b> The Oracle HCM products that support that activity.</p><p><b>Outcome</b> The record, decision or result passed to the next stage.</p></div></section>}
function SectionHead({n,over,title,children}:{n:string,over:string,title:string,children:React.ReactNode}){return <div className="heading"><div><span>{n}</span><p>{over}</p><h2>{title}</h2></div>{children}</div>}
function FoundationProcessFlows(){return <section className="foundation-flows"><div className="flow-intro"><small>SEE THE MODEL BEFORE THE SETUP</small><h3>Two simple Oracle HCM process maps</h3><p>Read from left to right. The first map explains how Oracle stores a worker. The second shows which organisation structures feed the worker’s assignment.</p></div><article className="flow-card"><header><span>01</span><div><small>PERSON AND ASSIGNMENT FLOW</small><h3>One person can have more than one assignment</h3></div></header><div className="person-flow"><div className="flow-node identity"><small>PERSON</small><b>Jenny Sharma</b><p>One identity and person number</p></div><span className="flow-arrow">→</span><div className="relationship-stack"><div className="flow-node relationship"><small>WORK RELATIONSHIP</small><b>CHC UK Ltd</b><p>Jenny’s employment connection to this Legal Employer</p></div><span className="flow-down">↓</span><div className="assignment-branch"><div className="flow-node assignment primary"><small>PRIMARY ASSIGNMENT</small><b>HR Analyst</b><p>UK Technology · London · Grade 4</p></div><div className="flow-node assignment"><small>ADDITIONAL ASSIGNMENT</small><b>Training Coordinator</b><p>CHC Academy · 0.2 FTE</p></div></div></div></div><div className="flow-rule"><b>Remember</b><span>The person tells us <em>who Jenny is</em>. The work relationship tells us <em>who employs her</em>. Each assignment tells us <em>what work she does and where</em>.</span></div><div className="flow-variation"><span>IF JENNY ALSO WORKS FOR CHC INDIA LTD</span><p>Oracle keeps the same person, creates another work relationship for the India Legal Employer, and creates the relevant India assignment beneath it.</p></div></article><article className="flow-card"><header><span>02</span><div><small>ENTERPRISE AND WORKFORCE STRUCTURE FLOW</small><h3>Organisation setup meets at the assignment</h3></div></header><div className="structure-flow"><div className="structure-column"><small>ENTERPRISE</small><div className="flow-node enterprise"><b>CHC Group</b><p>The overall organisation in Oracle HCM</p></div><span>↓</span><div className="flow-node legal"><b>CHC UK Ltd</b><p>Legal Entity + Legal Employer</p></div></div><div className="structure-column"><small>OPERATING STRUCTURE</small><div className="flow-node"><b>UK Technology</b><p>Business Unit</p></div><span>↓</span><div className="flow-node"><b>HR Systems</b><p>Department</p></div></div><div className="structure-column"><small>WORKFORCE STRUCTURES</small><div className="mini-nodes"><div><b>HR Analyst</b><p>Job</p></div><div><b>UK-HRIS-01</b><p>Position</p></div><div><b>Grade 4</b><p>Grade</p></div><div><b>London</b><p>Location</p></div></div></div><div className="assignment-result"><span>ALL VALUES COME TOGETHER HERE</span><b>Jenny’s Assignment</b><p>Legal Employer: CHC UK Ltd · BU: UK Technology · Department: HR Systems · Job: HR Analyst · Position: UK-HRIS-01 · Grade: 4 · Location: London</p></div></div><div className="flow-rule"><b>Simple distinction</b><span><em>Enterprise structures</em> explain the legal and operating organisation. <em>Workforce structures</em> describe the work, seat, level, team and workplace selected on the assignment.</span></div></article></section>}
function LessonVideo({topic,video}:{topic:string;video?:StudyVideo}){const[managed,setManaged]=useState<{title:string;url:string;resourceType:string;mandatory:number;oracleRelease:string;reviewedAt:string}[]>([]);useEffect(()=>{fetch("/api/content").then(r=>r.json()).then(d=>setManaged((d.resources||[]).filter((x:{lessonTitle:string;area:string})=>topic.toLowerCase().includes(x.lessonTitle.toLowerCase())||topic.toLowerCase().includes(x.area.toLowerCase())))).catch(()=>{})},[topic]);const featured=managed.find(x=>x.resourceType==="youtube"||x.resourceType==="trainer_video");function youtubeId(url:string){try{const u=new URL(url);if(u.hostname.includes("youtu.be"))return u.pathname.slice(1);if(u.hostname.includes("youtube.com"))return u.searchParams.get("v")||u.pathname.split("/").pop()||""}catch{}return ""}const managedId=featured?youtubeId(featured.url):"",shown=managedId?{id:managedId,title:featured!.title,source:"Trainer managed content"}:video;return <section className={`lesson-video ${shown?"has-video":"needs-video"}`}><header><div><small>WATCH THIS LESSON</small><h3>{shown?shown.title:`${topic} video lesson`}</h3><p>{shown?`Featured study video · ${shown.source}`:"A trainer video has not been attached to this lesson yet."}</p></div><span>VIDEO</span></header>{shown?<div className="video-frame"><iframe src={`https://www.youtube-nocookie.com/embed/${shown.id}`} title={shown.title} loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen/></div>:<div className="video-placeholder"><b>Trainer video will appear here</b><p>Until it is added, use the focused YouTube study search below. Open one useful video, then verify the behaviour in current Oracle documentation and your training instance.</p></div>}<footer>{managed.filter(x=>x!==featured).map(x=><a key={x.url} href={x.url} target="_blank" rel="noreferrer">{x.mandatory?"★ ":""}{x.title}{x.oracleRelease?` · ${x.oracleRelease}`:""}</a>)}<a href={youtubeSearch(topic)} target="_blank" rel="noreferrer">▶ Find more {topic} videos</a><a href={oracleLinks.books} target="_blank" rel="noreferrer">▤ Verify in Oracle documentation</a></footer></section>}
function AiPracticeGenerator({signedIn,unlocked}:{signedIn:boolean;unlocked:boolean}){const areas=["Approvals","Absence","Checklists","Workforce Structures","Trees","DFF","EFF","KFF","OTBI","Alert Composer","HDL/HSDL","Fast Formula","Work Schedules","Operations","Redwood/VBS","BIP/Extracts","Security/AOR"];const[area,setArea]=useState("Approvals"),[level,setLevel]=useState(3),[count,setCount]=useState(5),[tasks,setTasks]=useState<TraineeTask[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState("");async function generate(){setBusy(true);setError("");setTasks([]);const r=await fetch("/api/ai-tasks",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({area,level,count})});const d=await r.json();setBusy(false);if(!r.ok){setError(d.error||"Tasks could not be generated.");return}setTasks((d.tasks||[]).map((t:TraineeTask,i:number)=>({...t,id:`AI-${area.replace(/[^A-Z]/gi,"").slice(0,5).toUpperCase()}-${String(i+1).padStart(2,"0")}`,area,level:`Level ${level}`})))}return <section className={`ai-task-generator ${unlocked?"unlocked":"locked"}`}><div className="ai-generator-intro"><span>AI</span><div><small>PERSONALISED PRACTICE GENERATOR</small><h3>Finished the first five Approval tasks?</h3><p>Ask AI for additional end-to-end practice at the area and level you need. These are developmental tasks; trainer review remains the authority for scores and levels.</p></div></div>{!signedIn?<div className="ai-gate"><b>Sign in to check your eligibility</b><a href="/dashboard">Register or open my training →</a></div>:!unlocked?<div className="ai-gate"><b>Complete APP-01 to APP-05 first</b><p>All five tasks must be marked Reviewed or Completed by your trainer before AI practice unlocks.</p><span>{["APP-01","APP-02","APP-03","APP-04","APP-05"].map(x=><i key={x}>{x}</i>)}</span></div>:<><div className="ai-generator-controls"><label>Area<select value={area} onChange={e=>setArea(e.target.value)}>{areas.map(x=><option key={x}>{x}</option>)}</select></label><label>Level<select value={level} onChange={e=>setLevel(Number(e.target.value))}>{[1,2,3,4,5].map(x=><option value={x} key={x}>Level {x}</option>)}</select></label><label>Number of tasks<select value={count} onChange={e=>setCount(Number(e.target.value))}>{[1,3,5,10].map(x=><option value={x} key={x}>{x} task{x>1?"s":""}</option>)}</select></label><button disabled={busy} onClick={generate}>{busy?"AI is preparing tasks…":"Generate practice tasks →"}</button></div>{error&&<p className="ai-generator-error">{error}</p>}{tasks.length>0&&<div className="ai-generated-tasks"><header><small>NEW PRACTICE SET</small><b>{tasks.length} × {area} · Level {level}</b><button onClick={generate}>Generate a different set ↻</button></header>{tasks.map(t=><article key={t.id}><div><span>{t.id}</span><small>{t.level.toUpperCase()}</small><h4>{t.name}</h4><p>{t.brief}</p></div><TaskColumn title="BUSINESS REQUIREMENTS" items={t.requirements}/><TaskColumn title="MANDATORY DELIVERABLES" items={t.deliverables}/><TaskColumn title="MINIMUM TEST COVERAGE" items={t.tests}/><aside><b>ASSESSMENT FOCUS</b>{t.assessment}</aside></article>)}</div>}</>}</section>}
function Compare({l,a,b,c}:{l:string,a:string,b:string,c:string}){return <div className="compare-row"><b>{l}</b><span>{a}</span><span>{b}</span><span>{c}</span></div>}
function TaskColumn({title,items}:{title:string,items:string[]}){return <div className="task-column"><small>{title}</small><ol>{items.map((x,i)=><li key={x}><span>{String(i+1).padStart(2,"0")}</span>{x}</li>)}</ol></div>}
function ResourcePanel({topic,compact=false}:{topic:string;compact?:boolean}){return <section className={`oracle-resources ${compact?"compact":""}`}><div className="resource-intro"><small>GO AROUND ORACLE</small><h3>{topic} learning links</h3><p>Use videos to orient yourself, Oracle documentation to establish the current delivered behaviour, and Customer Connect to learn implementation experience and known edge cases.</p></div><div className="resource-links"><a href={youtubeSearch(topic)} target="_blank" rel="noreferrer"><b>▶</b><span>YouTube lessons<small>Existing videos for {topic}</small></span></a><a href={oracleLinks.videos} target="_blank" rel="noreferrer"><b>◉</b><span>Oracle HCM videos<small>Official Help Center collection</small></span></a><a href={oracleLinks.books} target="_blank" rel="noreferrer"><b>▤</b><span>Oracle documentation<small>Current HCM books and guides</small></span></a><a href={oracleLinks.community} target="_blank" rel="noreferrer"><b>◎</b><span>Customer Connect<small>Questions, answers and field experience</small></span></a></div><aside><b>HOW TO USE THESE LINKS</b><span>Watch → read the current guide → search Customer Connect → reproduce in TRAIN → write down what you verified.</span><em>Community and YouTube answers are evidence to investigate, not instructions to copy blindly.</em></aside></section>}
